// Código do navegador: interação, telas e chamadas para a API PHP.
const KEY='conecta-escola-v1';
const starter={support:'te@santainesrs.com.br',user:null,admin:false,platforms:[{id:'classroom',name:'Google Classroom',image:'',color:'#e9f7ee',summary:'Aprenda a acessar sua turma, acompanhar as atividades e enviar tarefas pelo Google Classroom. Use o e-mail institucional do estudante para entrar.',pdfs:[],videos:[],views:0},{id:'agenda',name:'Agenda Digital',image:'',color:'#edf0ff',summary:'Consulte comunicados, eventos e recados da escola. Mantenha as notificações ativadas para não perder nenhuma informação importante.',pdfs:[],videos:[],views:0},{id:'portal',name:'Portal do Aluno',image:'',color:'#fff2e8',summary:'Veja notas, frequência e informações acadêmicas no portal. Tenha em mãos o login fornecido pela secretaria.',pdfs:[],videos:[],views:0}],visits:[]};
let state;try{const saved=JSON.parse(localStorage.getItem(KEY));state={...structuredClone(starter),...(saved&&typeof saved==='object'?saved:{})}}catch{state=structuredClone(starter)}state.visits=Array.isArray(state.visits)?state.visits:[];state.platforms=Array.isArray(state.platforms)?state.platforms:structuredClone(starter.platforms);state.admin=false;if(state.user&&!/^\d{8}$/.test(String(state.user.enrollment||'')))state.user=null;for(const visit of state.visits){if(!visit||typeof visit!=='object')continue;if(!visit.openedAt&&visit.time){visit.openedAt=visit.time;visit.exitedAt=visit.time;visit.durationSeconds=0}}let storeIcons={play:'',apple:''};let page='home',selected=null,adminTab='platforms',menuOpen=false,activeActivity=null,pendingPlatformImage=null,activityLoadPending=false,contentConfigured=false,contentRevision='',contentSyncing=false,rosterMeta={count:0,importedAt:null},rosterListing={students:[],total:0,page:1,pages:1,pageSize:100},rosterQuery='',rosterLoading=false;
if(state.support==='suporte@colegio.edu.br')state.support='te@santainesrs.com.br';save()
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){const stored={support:state.support,user:state.user,visits:state.visits||[]};if(!contentConfigured)stored.platforms=state.platforms;try{localStorage.setItem(KEY,JSON.stringify(stored))}catch{localStorage.setItem(KEY,JSON.stringify({support:state.support,user:state.user,visits:[]}))}}
async function persistSiteContent(){const response=await fetch('/api/admin/content',{method:'PUT',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({support:state.support,platforms:state.platforms,storeIcons})});let result={};try{result=await response.json()}catch{}if(!response.ok)throw new Error(result.error||'Não foi possível salvar. Tente novamente.');contentConfigured=true;contentRevision=result.revision||'';save()}
async function syncSiteContent(){if(contentSyncing)return;contentSyncing=true;const revisionAtRequest=contentRevision;try{const response=await fetch('/api/content',{credentials:'same-origin',cache:'no-store',headers:contentRevision?{'If-None-Match':contentRevision}:{}});if(response.status===304)return;if(!response.ok)return;const result=await response.json();if(revisionAtRequest!==contentRevision)return;if(result.configured){if(result.revision!==contentRevision&&!$('#modal-root').children.length){state.platforms=result.content.platforms||[];state.support=result.content.support||state.support;storeIcons=result.content.storeIcons||storeIcons;contentConfigured=true;contentRevision=result.revision;save();render()}}else if(state.admin){await persistSiteContent()}}catch{}finally{contentSyncing=false}}
function platformIcon(p){return `<div class="platform-icon">${p.image?`<img src="${esc(p.image)}" alt="">`:'<span class="platform-placeholder" aria-hidden="true">+</span>'}</div>`}
function createActivity(platform,kind){if(activeActivity)finishActivity();const entry={id:'a'+Date.now()+Math.random().toString(36).slice(2),name:state.user?.name||'Visitante',role:state.user?.role||'—',platform,kind,openedAt:new Date().toISOString(),exitedAt:null};state.visits.push(entry);activeActivity=entry.id;save();fetch('/api/activities',{method:'POST',credentials:'same-origin',keepalive:true,headers:{'Content-Type':'application/json'},body:JSON.stringify(entry)}).catch(()=>{})}
function finishActivity(){if(!activeActivity)return;const entry=state.visits.find(v=>v.id===activeActivity);if(entry&&!entry.exitedAt){entry.exitedAt=new Date().toISOString();entry.durationSeconds=Math.max(0,Math.round((Date.parse(entry.exitedAt)-Date.parse(entry.openedAt))/1000));save();fetch(`/api/activities/${encodeURIComponent(entry.id)}/exit`,{method:'PATCH',credentials:'same-origin',keepalive:true}).catch(()=>{})}activeActivity=null}
function formatActivityTime(value){return value?new Date(value).toLocaleString('pt-BR'):'Em andamento'}
function formatDuration(seconds){if(seconds==null)return '—';if(seconds<60)return `${seconds} s`;return `${Math.floor(seconds/60)} min ${seconds%60} s`}function email(){return esc(state.support||'te@santainesrs.com.br')}
function header(){return `<header class="topbar"><div class="brand"><img class="brand-mark" src="assets/colegio-santa-ines.png" alt="Símbolo do Colégio Santa Inês"><div>Colégio Santa Inês<small>CENTRAL DE PLATAFORMAS</small></div></div><div class="navright">${state.admin?'<span class="role-pill">Equipe TE</span>':state.user?`<span class="user-pill">${esc(state.user.name)} · ${esc(state.user.role)}</span>`:''}<button class="menu-toggle" aria-label="Abrir menu" aria-expanded="${menuOpen}" onclick="toggleMenu()"><span></span><span></span><span></span></button></div>${menuOpen?`<nav class="menu-pop"><button onclick="goHome()">⌂ &nbsp;Página inicial</button>${state.admin?`<button onclick="adminTab='platforms';menuOpen=false;render()">▦ &nbsp;Gerenciar plataformas</button><button onclick="adminTab='roster';menuOpen=false;render();loadRosterMeta()">♙ &nbsp;Lista de estudantes</button><button onclick="adminTab='access';menuOpen=false;render();loadActivityRecords()">◷ &nbsp;Registros de acesso</button><button onclick="adminTab='settings';menuOpen=false;render()">✉ &nbsp;Contato de suporte</button><button onclick="logoutAdmin()">↪ &nbsp;Sair da equipe</button>`:`<button onclick="openAdmin()">♙ &nbsp;Área da equipe TE</button>${state.user?`<button onclick="logoutUser()">↪ &nbsp;Trocar usuário</button>`:''}`}</nav>`:''}</header>`}
function footer(){return `<footer class="support">Precisa de ajuda? Fale com a equipe de tecnologia: <a href="mailto:${email()}">${email()}</a></footer>`}
function toggleMenu(){menuOpen=!menuOpen;render()}function goHome(){finishActivity();menuOpen=false;if(state.admin){state.admin=false}page='home';render()}
function render(){let content=state.admin?adminView():page==='login'?loginView():page==='reset'?resetView():page==='detail'?detailView():homeView();$('#app').innerHTML=`<div class="shell">${header()}${content}${footer()}</div>`;if(page==='reset')loadResetOptions()}
function homeView(){if(!state.user)return `<main class="login"><section class="card login-box"><div class="eyebrow">Bem-vindo à central</div><h1>Acesse os tutoriais da escola</h1><p class="sub">Informe seu nome e sobrenome para continuar. Você poderá consultar os materiais das plataformas a qualquer momento.</p><div class="field"><label>Nome e sobrenome</label><input id="userName" placeholder="Ex.: Ana Silva" autocomplete="name"></div><div class="field"><label>Seu perfil</label><select id="userRole"><option value="Responsável">Responsável</option><option value="Estudante">Estudante</option></select></div><button class="btn primary" style="width:100%;margin-top:4px" onclick="enterUser()">Entrar na central →</button><p class="hint">Ao continuar, você concorda que a equipe escolar registre os acessos às páginas e materiais para acompanhar o uso dos tutoriais.</p></section></main>`;
return `<main class="wrap"><section class="welcome"><div><div class="eyebrow">Central de aprendizagem</div><h1 class="heading home-heading">Olá, ${esc(state.user.name.split(' ')[0])} </h1><p class="sub">Acesse os guias e tutoriais das plataformas utilizadas na escola.</p></div><button class="btn quiet" onclick="logoutUser()">Trocar usuário</button></section><div class="section-title">Plataformas disponíveis <span style="color:#9aa2b1;font-weight:500;font-size:13px">· ${state.platforms.length}</span></div><section class="grid">${state.platforms.length?state.platforms.map(p=>`<article class="card platform user-platform" onclick="openPlatform('${p.id}')">${platformIcon(p)}<h3>${esc(p.name)}</h3><p>${esc(p.summary).slice(0,95)}${p.summary.length>95?'…':''}</p><div class="card-foot"><span>${p.pdfs.length} PDFs · ${p.videos.length} vídeos</span><span class="arrow">Ver tutoriais ↗</span></div></article>`).join(''):'<div class="card empty">Ainda não há plataformas publicadas.</div>'}</section></main>`}
function detailView(){let p=state.platforms.find(x=>x.id===selected);if(!p){page='home';return homeView()}return `<main class="wrap"><button class="crumb" onclick="goHome()">← Voltar às plataformas</button><div class="detail-head">${platformIcon(p)}<div><h1>${esc(p.name)}</h1><p>Tutoriais e materiais de apoio</p></div></div><div class="info-box"><strong>Como acessar</strong>${esc(p.summary)}</div><h2 class="section-title">Materiais para aprender</h2><div class="materials">${p.pdfs.map(f=>materialCard(f,'pdf',p.id)).join('')}${p.videos.map(f=>materialCard(f,'video',p.id)).join('')}${!p.pdfs.length&&!p.videos.length?'<div class="card empty">Os materiais desta plataforma serão publicados em breve.</div>':''}</div></main>`}
function materialCard(f,type,id){return `<article class="card material"><div class="fileicon">${type==='pdf'?'PDF':'VÍDEO'}</div><div><h3>${esc(f.name)}</h3><small>${type==='pdf'?'Documento PDF':'Vídeo tutorial'}</small></div><button class="btn quiet" onclick="openMaterial('${id}','${type}','${esc(f.id)}')">${type==='pdf'?'Visualizar':'Assistir'} ↗</button></article>`}
function enterUser(){let name=$('#userName').value.trim().replace(/\s+/g,' ');if(name.split(' ').length<2){toast('Digite seu nome e sobrenome para continuar.');return}state.user={name,role:$('#userRole').value};save();page='home';render()}
function openPlatform(id){finishActivity();selected=id;page='detail';let p=state.platforms.find(x=>x.id===id);if(state.user){p.views=(p.views||0)+1;createActivity(p.name,'Página')}save();render()}
function openMaterial(pid,type,fid){let p=state.platforms.find(x=>x.id===pid),f=p[type==='pdf'?'pdfs':'videos'].find(x=>x.id===fid);if(!f)return;createActivity(p.name,type==='pdf'?'PDF':'Vídeo');if(f.data){try{const comma=f.data.indexOf(',');const mime=f.data.slice(5,comma).split(';')[0]||'application/octet-stream';const raw=atob(f.data.slice(comma+1));const bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);const url=URL.createObjectURL(new Blob([bytes],{type:mime}));const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener';a.click();setTimeout(()=>URL.revokeObjectURL(url),120000)}catch(error){toast('Não foi possível abrir este arquivo. Tente novamente.')}}else if(f.url){window.open(f.url,'_blank','noopener')}else toast('Este material ainda não possui um arquivo vinculado.');render()}
let pageWasHidden=false;document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'){pageWasHidden=true;if(state.visits.find(v=>v.id===activeActivity)?.kind==='Página')finishActivity()}else if(pageWasHidden){pageWasHidden=false;if(state.visits.find(v=>v.id===activeActivity)&&state.visits.find(v=>v.id===activeActivity).kind!=='Página')finishActivity();if(page==='detail'&&state.user&&!state.admin){const platform=state.platforms.find(p=>p.id===selected);if(platform)createActivity(platform.name,'Página')}}});window.addEventListener('pagehide',finishActivity);
function logoutUser(){finishActivity();state.user=null;menuOpen=false;page='home';render()}function openAdmin(){finishActivity();menuOpen=false;page='login';render()}async function logoutAdmin(){try{await fetch('/api/logout',{method:'POST',credentials:'same-origin'})}catch{}state.admin=false;menuOpen=false;page='home';render()}

function loginView(){return `<main class="login"><section class="card login-box"><div class="eyebrow">Acesso restrito</div><h1>Equipe de tecnologia</h1><p class="sub">Entre com o e-mail e a senha da equipe para gerenciar a central.</p><form onsubmit="event.preventDefault();loginAdmin()"><div class="field"><label for="adminEmail">E-mail</label><input id="adminEmail" type="email" autocomplete="username" placeholder="te@santainesrs.com.br" required></div><div class="field"><label for="adminPass">Senha</label><input id="adminPass" type="password" autocomplete="current-password" placeholder="Sua senha" required></div><button class="btn primary" style="width:100%" type="submit">Entrar</button></form><button class="btn outline" style="width:100%;margin-top:9px" onclick="page='reset';render()">Esqueci minha senha</button><button class="btn quiet" style="width:100%;margin-top:9px" onclick="page='home';render()">Voltar</button></section></main>`}
function resetView(){return `<main class="login"><section class="card login-box"><div class="eyebrow">Recuperação segura</div><h1>Redefinir senha</h1><p class="sub">Enviaremos um código temporário ao e-mail cadastrado da equipe TE.</p><div class="field"><label>E-mail da equipe</label><input id="resetEmail" type="email" autocomplete="username" placeholder="email@santainesrs.com.br"></div><button id="requestResetButton" class="btn primary" style="width:100%" onclick="requestPasswordReset()">Enviar código</button><div id="resetCodeArea" class="hidden"><p class="hint">Confira sua caixa de entrada e a pasta de spam. O código vale por 10 minutos.</p><div class="field"><label>Código recebido</label><input id="resetCode" inputmode="numeric" autocomplete="one-time-code" maxlength="6" placeholder="000000"></div><div class="field"><label>Nova senha (mínimo 12 caracteres)</label><input id="resetPassword" type="password" autocomplete="new-password"></div><div class="field"><label>Confirme a nova senha</label><input id="resetPasswordConfirm" type="password" autocomplete="new-password"></div><button class="btn primary" style="width:100%" onclick="completePasswordReset()">Salvar nova senha</button></div><div id="localResetOption" class="hidden" style="border-top:1px solid var(--line);margin-top:22px;padding-top:20px"><h2 style="font:700 18px Manrope;margin:0 0 8px">Está neste computador?</h2><p class="hint">Faça uma redefinição local de uso único. Ela só funciona neste endereço local e você mesmo define a senha.</p><button class="btn outline" style="width:100%" onclick="$('#localResetForm').classList.remove('hidden')">Redefinir neste computador</button><div id="localResetForm" class="hidden" style="margin-top:16px"><p class="hint">A única conta TE cadastrada neste computador será redefinida.</p><div class="field"><label>Nova senha (mínimo 12 caracteres)</label><input id="localResetPassword" type="password" autocomplete="new-password"></div><div class="field"><label>Confirme a nova senha</label><input id="localResetConfirm" type="password" autocomplete="new-password"></div><button class="btn primary" style="width:100%" onclick="completeLocalPasswordReset()">Salvar nova senha</button></div></div><button class="btn quiet" style="width:100%;margin-top:9px" onclick="page='login';render()">Voltar ao acesso</button></section></main>`}
async function loadResetOptions(){try{const response=await fetch('/api/password-reset/local',{credentials:'same-origin'});if(response.ok)$('#localResetOption')?.classList.remove('hidden')}catch{}}
async function completeLocalPasswordReset(){const password=$('#localResetPassword').value,confirmation=$('#localResetConfirm').value;if(password.length<12){toast('A nova senha deve ter pelo menos 12 caracteres.');return}if(password!==confirmation){toast('As senhas não coincidem.');return}const button=$('#localResetForm .primary');button.disabled=true;try{const response=await fetch('/api/password-reset/local',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({password,confirmation})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Não foi possível concluir a redefinição.');page='login';render();toast(result.message)}catch(error){toast(error.message||'Não foi possível concluir a redefinição.')}finally{if($('#localResetForm .primary'))$('#localResetForm .primary').disabled=false}}
async function requestPasswordReset(){const button=$('#requestResetButton'),email=$('#resetEmail').value.trim();button.disabled=true;try{const response=await fetch('/api/password-reset/request',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Não foi possível solicitar o código.');$('#resetCodeArea').classList.remove('hidden');button.textContent='Enviar outro código';toast(result.message)}catch(error){toast(error.message||'Não foi possível solicitar o código.')}finally{button.disabled=false}}
async function completePasswordReset(){const email=$('#resetEmail').value.trim(),code=$('#resetCode').value.trim(),password=$('#resetPassword').value,confirmation=$('#resetPasswordConfirm').value;if(password.length<12){toast('A nova senha deve ter pelo menos 12 caracteres.');return}if(password!==confirmation){toast('As senhas não coincidem.');return}const button=$('#resetCodeArea .primary');button.disabled=true;try{const response=await fetch('/api/password-reset/complete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,code,password})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Não foi possível concluir a redefinição.');page='login';render();$('#adminEmail').value=email;toast(result.message)}catch(error){toast(error.message||'Não foi possível concluir a redefinição.')}finally{if($('#resetCodeArea .primary'))$('#resetCodeArea .primary').disabled=false}}
async function loginAdmin(){const button=$('.login-box .primary');button.disabled=true;try{const response=await fetch('/api/login',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:$('#adminEmail').value,password:$('#adminPass').value})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Não foi possível entrar.');state.admin=true;while(contentSyncing)await new Promise(resolve=>setTimeout(resolve,40));await syncSiteContent();page='admin';render();if(adminTab==='year')loadYearPlan()}catch(error){toast(error.message==='Failed to fetch'?'Não foi possível conectar. Abra a central pelo endereço do sistema.':error.message)}finally{if($('.login-box .primary'))$('.login-box .primary').disabled=false}}
fetch('/api/session',{credentials:'same-origin'}).then(r=>r.json()).then(async s=>{state.admin=Boolean(s.authenticated);if(state.admin){await syncSiteContent();page='admin';render()}}).catch(()=>{});setInterval(syncSiteContent,1800);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')syncSiteContent()});
function adminView(){let visits=state.visits||[];return `<main class="wrap"><div class="welcome"><div><div class="eyebrow">Painel de gestão</div><h1 class="heading">Área da equipe TE</h1><p class="sub">Gerencie plataformas, materiais e acompanhe o acesso aos tutoriais.</p></div></div><nav class="adminbar"><button class="tab ${adminTab==='platforms'?'active':''}" onclick="adminTab='platforms';render()">Plataformas</button><button class="tab ${adminTab==='access'?'active':''}" onclick="adminTab='access';render();loadActivityRecords()">Acessos</button><button class="tab ${adminTab==='settings'?'active':''}" onclick="adminTab='settings';render()">Contato de suporte</button></nav>${adminTab==='platforms'?platformAdmin():adminTab==='access'?accessAdmin():settingsAdmin()}</main>`}
function platformAdmin(){return `<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:16px"><div><h2 class="section-title" style="margin:0 0 4px">Plataformas</h2><span style="color:var(--muted);font-size:12px">${state.platforms.length} cadastradas</span></div><button class="btn primary" onclick="editPlatform()">＋ Nova plataforma</button></div><div class="admin-list">${state.platforms.map(p=>`<div class="card admin-row">${platformIcon(p)}<div><h3>${esc(p.name)}</h3><small>${p.pdfs.length} PDFs · ${p.videos.length} vídeos · ${p.views||0} visualizações da página</small></div><div class="spacer"></div><div class="actions"><button class="btn quiet" onclick="editPlatform('${p.id}')">Editar</button><button class="btn danger" onclick="deletePlatform('${p.id}')">Excluir</button></div></div>`).join('')||'<div class="card empty">Nenhuma plataforma cadastrada.</div>'}</div>`}
async function loadActivityRecords(){if(activityLoadPending)return;activityLoadPending=true;try{const response=await fetch('/api/admin/activities',{credentials:'same-origin'});if(!response.ok)throw new Error('Não foi possível carregar os registros.');const data=await response.json();state.visits=data.activities||[];save();if(state.admin&&adminTab==='access')render()}catch{toast('Não foi possível atualizar os registros agora.')}finally{activityLoadPending=false}}
function accessAdmin(){let unique=new Set(state.visits.map(v=>v.name+'|'+v.role));return `<div style="display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:16px"><h2 class="section-title" style="margin:0">Registros de atividade</h2><button class="btn danger" onclick="confirmClearVisits()" ${state.visits.length?'':'disabled'}>Excluir registros</button></div><div class="stats"><div class="card stat"><span>Acessos registrados</span><strong>${state.visits.length}</strong></div><div class="card stat"><span>Pessoas identificadas</span><strong>${unique.size}</strong></div><div class="card stat"><span>Plataformas</span><strong>${state.platforms.length}</strong></div></div><div class="card" style="overflow:auto;padding:7px 18px"><table class="access-table"><thead><tr><th>Nome</th><th>Perfil</th><th>Plataforma</th><th>Conteúdo</th><th>Entrada</th><th>Saída</th><th>Tempo</th></tr></thead><tbody>${[...state.visits].reverse().map(v=>`<tr><td>${esc(v.name)}</td><td><span class="badge">${esc(v.role)}</span></td><td>${esc(v.platform)}</td><td>${esc(v.kind)}</td><td>${formatActivityTime(v.openedAt||v.time)}</td><td>${v.exitedAt?formatActivityTime(v.exitedAt):v.id===activeActivity?'Em andamento':'—'}</td><td>${formatDuration(v.durationSeconds)}</td></tr>`).join('')||'<tr><td colspan="7" style="text-align:center;color:#9aa2b1;padding:30px">Os acessos aparecerão aqui quando os usuários explorarem os tutoriais.</td></tr>'}</tbody></table></div><p class="hint">A central registra os horários de entrada e saída das páginas e materiais.</p>`}

function confirmClearVisits(){showModal(`<h2>Excluir registros de atividade</h2><p class="sub" style="font-size:15px;margin-bottom:18px">Esta ação apagará todos os registros de acesso salvos neste navegador. Para confirmar, digite <b>CONFIRMAR</b> no campo abaixo.</p><div class="field"><label>Confirmação</label><input id="clearConfirm" autocomplete="off" placeholder="Digite CONFIRMAR" oninput="$('#clearButton').disabled=this.value!=='CONFIRMAR'"></div><div class="modal-actions"><button class="btn quiet" onclick="closeModal()">Cancelar</button><button id="clearButton" class="btn danger" disabled onclick="clearVisits()">Excluir registros</button></div>`)}async function clearVisits(){if($('#clearConfirm')?.value!=='CONFIRMAR')return;try{const response=await fetch('/api/admin/activities',{method:'DELETE',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirmation:$('#clearConfirm').value})});if(!response.ok)throw new Error();state.visits=[];save();closeModal();render();toast('Registros de atividade excluídos.')}catch{toast('Não foi possível excluir os registros agora.')}}
function settingsAdmin(){return `<div class="card" style="max-width:650px"><h2 class="section-title" style="margin-top:0">E-mail de suporte</h2><p class="sub" style="font-size:13px;margin-bottom:20px">Este endereço aparecerá centralizado no rodapé de todas as telas da central.</p><div class="field"><label>E-mail</label><input id="supportEmail" type="email" value="${email()}" placeholder="te@santainesrs.com.br"></div><button class="btn primary" style="margin-top:16px" onclick="saveSupport()">Salvar contato</button></div>`}
async function saveSupport(){let val=$('#supportEmail').value.trim();if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val)){toast('Informe um e-mail válido.');return}const previous=state.support;state.support=val;try{await persistSiteContent();render();toast('Contato de suporte atualizado.')}catch(error){state.support=previous;toast(error.message||'Não foi possível salvar o e-mail.')}}
function editPlatform(id){let p=state.platforms.find(x=>x.id===id),editing=!!p;let data=p||{id:'p'+Date.now(),name:'',image:'',color:'#eaf2ff',summary:'',pdfs:[],videos:[],views:0};pendingPlatformImage=data.image||null;const preview=pendingPlatformImage?`<img src="${esc(pendingPlatformImage)}" alt="Prévia do ícone">`:'<span>Cole a imagem do ícone aqui com Ctrl+V</span>';showModal(`<h2>${editing?'Editar plataforma':'Nova plataforma'}</h2><div class="formgrid"><div class="field full"><label>Imagem do ícone</label><div id="platformPaste" class="paste-zone${pendingPlatformImage?' has-image':''}" tabindex="0" role="button" aria-label="Cole a imagem do ícone com Ctrl+V">${preview}</div><small class="paste-help">Copie a imagem e cole aqui usando Ctrl+V.</small></div><div class="field full"><label>Nome da plataforma</label><input id="pName" value="${esc(data.name)}" placeholder="Ex.: Google Classroom"></div><div class="field full"><label>Texto explicativo sobre como acessar</label><textarea id="pSummary" placeholder="Explique como entrar e usar a plataforma...">${esc(data.summary)}</textarea></div><div class="field"><label>Adicionar PDF tutorial</label><input id="pPdf" type="file" accept="application/pdf,.pdf" multiple></div><div class="field"><label>Adicionar vídeo (arquivo)</label><input id="pVideo" type="file" accept="video/*" multiple></div><div class="field full"><label>Ou adicionar links de vídeos (um link por linha)</label><textarea id="pVideoUrl" placeholder="Cole links de vídeos, um por linha"></textarea></div><div class="field full"><label>Materiais cadastrados</label><div style="font-size:14px;color:#5f6f87">${data.pdfs.map(f=>'PDF · '+esc(f.name)).concat(data.videos.map(f=>'Vídeo · '+esc(f.name))).join('<br>')||'Nenhum material adicionado.'}</div></div></div><div class="modal-actions"><button class="btn quiet" onclick="closeModal()">Cancelar</button><button id="savePlatformButton" class="btn primary" onclick="savePlatform('${data.id}',${editing})">Salvar plataforma</button></div>`);$('#platformPaste').focus()}
function pastePlatformImage(event){if(!$('#platformPaste'))return;const items=[...(event.clipboardData?.items||[])],imageItem=items.find(item=>item.type.startsWith('image/'));if(!imageItem){toast('Copie uma imagem antes de usar Ctrl+V.');return}event.preventDefault();const file=imageItem.getAsFile();if(!file)return;const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{const canvas=document.createElement('canvas'),scale=Math.min(1,360/Math.max(img.width,img.height));canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);pendingPlatformImage=canvas.toDataURL('image/png');const zone=$('#platformPaste');if(zone){zone.classList.add('has-image');zone.innerHTML=`<img src="${pendingPlatformImage}" alt="Prévia do ícone">`}};img.src=reader.result};reader.readAsDataURL(file)}
function readAsDataURL(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Não foi possível ler um dos arquivos.'));reader.readAsDataURL(file)})}
async function savePlatform(id,editing){const button=$('#savePlatformButton'),original=button.textContent;let name=$('#pName').value.trim(),summary=$('#pSummary').value.trim();if(!name||!summary){toast('Preencha o nome e o texto explicativo.');return}if(!pendingPlatformImage){toast('Cole uma imagem para o ícone da plataforma.');return}button.disabled=true;button.textContent='Salvando…';const previous=state.platforms;try{let current=previous.find(x=>x.id===id),p=current?structuredClone(current):{id,name,image:pendingPlatformImage,color:'#eaf2ff',summary,pdfs:[],videos:[],views:0};p.name=name;p.image=pendingPlatformImage;p.color='#eaf2ff';p.summary=summary;const files=[...$('#pPdf').files,...$('#pVideo').files];const loaded=await Promise.all(files.map(async file=>({file,data:await readAsDataURL(file)})));for(const {file,data} of loaded){const material={id:'m'+Date.now()+Math.random(),name:file.name,data};(file.type==='application/pdf'?p.pdfs:p.videos).push(material)}const urls=$('#pVideoUrl').value.split(/\s+/).filter(x=>/^https?:\/\//.test(x));for(const url of urls)p.videos.push({id:'m'+Date.now()+Math.random(),name:'Vídeo tutorial',url});state.platforms=current?previous.map(item=>item.id===id?p:item):[...previous,p];try{await persistSiteContent()}catch(error){state.platforms=previous;throw error}closeModal();render();toast('Alterações salvas.')}catch(error){toast(error.message||'Não foi possível salvar. Tente novamente.')}finally{if($('#savePlatformButton')){button.disabled=false;button.textContent=original}}}

document.addEventListener('paste',pastePlatformImage);
async function deletePlatform(id){if(!confirm('Excluir esta plataforma e os materiais cadastrados?'))return;const previous=state.platforms;state.platforms=state.platforms.filter(x=>x.id!==id);try{await persistSiteContent();render();toast('Plataforma excluída.')}catch(error){state.platforms=previous;render();toast(error.message||'Não foi possível excluir a plataforma.')}}
function showModal(html){$('#modal-root').innerHTML=`<div class="modal-back" onclick="if(event.target===this)closeModal()"><section class="modal">${html}</section></div>`}function closeModal(){$('#modal-root').innerHTML=''}function toast(msg){let old=$('.toast');if(old)old.remove();let t=document.createElement('div');t.className='toast';t.textContent=msg;document.body.append(t);setTimeout(()=>t.remove(),2800)}
function save(){const stored={support:state.support};if(!contentConfigured)stored.platforms=state.platforms;try{localStorage.setItem(KEY,JSON.stringify(stored))}catch{localStorage.setItem(KEY,JSON.stringify({support:state.support}))}}
function homeView(){if(!state.user)return `<main class="login"><section class="card login-box"><div class="eyebrow">Bem-vindo à central</div><h1>Acesse os tutoriais da escola</h1><p class="sub">Use a matrícula e o nome do estudante que constam na lista da escola. Depois, indique se você é estudante ou responsável.</p><div class="field"><label for="userEnrollment">Matrícula do estudante (8 dígitos)</label><input id="userEnrollment" type="text" inputmode="numeric" autocomplete="off" maxlength="8" pattern="[0-9]{8}" placeholder="Ex.: 00123456"></div><div class="field"><label for="studentName">Nome do estudante</label><input id="studentName" autocomplete="off" placeholder="Como aparece na lista escolar"></div><div class="field"><label for="userRole">Seu perfil</label><select id="userRole"><option value="Responsável">Responsável</option><option value="Estudante">Estudante</option></select></div><button class="btn primary" style="width:100%;margin-top:4px" onclick="enterUser()">Entrar na central →</button><p class="hint">O acesso é conferido com a lista importada pela equipe TE. Os acessos aos tutoriais serão registrados para acompanhamento.</p></section></main>`;return `<main class="wrap"><section class="welcome"><div><div class="eyebrow">Central de aprendizagem</div><h1 class="heading home-heading">Olá, ${esc(state.user.name.split(' ')[0])}</h1><p class="sub">Acesse os guias e tutoriais das plataformas utilizadas na escola.</p></div><button class="btn quiet" onclick="logoutUser()">Trocar usuário</button></section><div class="section-title">Plataformas disponíveis <span style="color:#9aa2b1;font-weight:500;font-size:13px">· ${state.platforms.length}</span></div><section class="grid">${state.platforms.length?state.platforms.map(p=>`<article class="card platform user-platform" onclick="openPlatform('${p.id}')">${platformIcon(p)}<h3>${esc(p.name)}</h3><p>${esc(p.summary).slice(0,95)}${p.summary.length>95?'…':''}</p><div class="card-foot"><span>${p.pdfs.length} PDFs · ${p.videos.length} vídeos</span><span class="arrow">Ver tutoriais ↗</span></div></article>`).join(''):'<div class="card empty">Ainda não há plataformas cadastradas.</div>'}</section></main>`}
async function enterUser(){const enrollment=$('#userEnrollment').value.trim(),name=$('#studentName').value.trim().replace(/\s+/g,' '),role=$('#userRole').value,button=$('.login-box .primary');if(!/^\d{8}$/.test(enrollment)){toast('Digite a matrícula com exatamente 8 números.');return}if(!name){toast('Digite o nome do estudante como aparece na lista escolar.');return}button.disabled=true;try{const response=await fetch('/api/student/login',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({enrollment,name,role})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Não foi possível conferir os dados.');state.user={...result.student,role:result.role};page='home';render()}catch(error){toast(error.message==='Failed to fetch'?'Não foi possível conectar ao sistema. Tente novamente.':error.message)}finally{if($('.login-box .primary'))$('.login-box .primary').disabled=false}}
function createActivity(platform,kind){if(!state.user)return;if(activeActivity)finishActivity();const entry={id:'a'+Date.now()+Math.random().toString(36).slice(2),name:state.user.name,enrollment:state.user.enrollment,className:state.user.className,role:state.user.role,platform,kind,openedAt:new Date().toISOString(),exitedAt:null};state.visits.push(entry);activeActivity=entry.id;fetch('/api/activities',{method:'POST',credentials:'same-origin',keepalive:true,headers:{'Content-Type':'application/json'},body:JSON.stringify(entry)}).catch(()=>{})}
async function loadRosterMeta(){try{const response=await fetch('/api/admin/roster',{credentials:'same-origin'});if(!response.ok)throw new Error();rosterMeta=await response.json();await loadRosterPage(1,rosterQuery,false);if(state.admin&&adminTab==='roster')render()}catch{toast('Não foi possível consultar a lista de estudantes.')}}
async function loadRosterPage(page=1,query=rosterQuery,shouldRender=true){rosterLoading=true;try{const params=new URLSearchParams({page:String(page),q:query});const response=await fetch(`/api/admin/roster/students?${params}`,{credentials:'same-origin',cache:'no-store'});if(response.status===401)throw new Error('A sessão da equipe expirou. Entre novamente.');if(!response.ok)throw new Error('Não foi possível carregar os estudantes.');rosterListing=await response.json();rosterQuery=query;if(shouldRender&&state.admin&&adminTab==='roster')render()}catch(error){toast(error.message)}finally{rosterLoading=false}}
function searchRoster(){loadRosterPage(1,$('#rosterSearch')?.value.trim()||'')}
function adminView(){return `<main class="wrap"><div class="welcome"><div><div class="eyebrow">Painel de gestão</div><h1 class="heading">Área da equipe TE</h1><p class="sub">Gerencie plataformas, lista de estudantes e acompanhe o acesso aos tutoriais.</p></div></div><nav class="adminbar"><button class="tab ${adminTab==='platforms'?'active':''}" onclick="adminTab='platforms';render()">Plataformas</button><button class="tab ${adminTab==='roster'?'active':''}" onclick="adminTab='roster';render();loadRosterMeta()">Lista de estudantes</button><button class="tab ${adminTab==='access'?'active':''}" onclick="adminTab='access';render();loadActivityRecords()">Acessos</button><button class="tab ${adminTab==='settings'?'active':''}" onclick="adminTab='settings';render()">Contato de suporte</button></nav>${adminTab==='platforms'?platformAdmin():adminTab==='roster'?rosterAdmin():adminTab==='access'?accessAdmin():settingsAdmin()}</main>`}
function rosterAdmin(){const first=rosterListing.total?(rosterListing.page-1)*rosterListing.pageSize+1:0,last=Math.min(rosterListing.page*rosterListing.pageSize,rosterListing.total);return `<section class="card" style="max-width:900px"><h2 class="section-title" style="margin-top:0">Importar lista de estudantes</h2><p class="sub" style="font-size:15px;margin-bottom:16px">Envie a planilha atualizada da escola. A importação substitui a lista anterior e deve ser feita no início de cada ano letivo.</p><div class="card" style="background:#f5f8fd;margin-bottom:20px"><strong>Colunas esperadas</strong><p style="margin:8px 0 0;line-height:1.7">A · Matrícula (8 dígitos) &nbsp; B · Nome do estudante &nbsp; C · Turma</p><small>A primeira linha pode conter os títulos das colunas. No Excel, salve como Pasta de Trabalho (.xlsx) ou CSV.</small></div><div class="field"><label for="rosterFile">Planilha Excel (.xlsx) ou CSV exportado do Excel</label><input id="rosterFile" type="file" accept=".xlsx,.csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,text/csv" onchange="showRosterFile()"><div id="rosterFileStatus" class="hint" style="margin-top:8px">Escolha um arquivo .xlsx ou .csv de até 25 MB.</div></div><button id="importRosterButton" class="btn primary" style="margin-top:16px" onclick="importStudentRoster()" disabled>Enviar e importar planilha</button><p id="rosterUploadStatus" class="hint" role="status" aria-live="polite" style="margin-top:14px"></p><div class="hint" style="margin-top:22px">${rosterMeta.count?`Lista atual: ${rosterMeta.count} estudantes. Importada em ${formatActivityTime(rosterMeta.importedAt)}.`:'Nenhuma lista de estudantes foi importada ainda.'}</div></section><section class="card" style="margin-top:20px"><div style="display:flex;justify-content:space-between;align-items:flex-end;gap:14px;flex-wrap:wrap"><div><h2 class="section-title" style="margin:0 0 5px">Estudantes cadastrados</h2><p class="hint" style="margin:0">${rosterListing.total} estudante${rosterListing.total===1?'':'s'} · ${rosterLoading?'Carregando…':rosterListing.total?`Exibindo ${first}–${last}`:'Nenhum estudante cadastrado'}</p></div><div style="display:flex;gap:8px;flex:1;min-width:min(100%,300px);max-width:470px"><input id="rosterSearch" type="search" value="${esc(rosterQuery)}" placeholder="Buscar matrícula, nome ou turma" aria-label="Buscar estudantes" onkeydown="if(event.key==='Enter')searchRoster()" style="min-width:0;flex:1;border:1px solid var(--line);border-radius:10px;padding:11px 12px"><button class="btn primary" onclick="searchRoster()">Buscar</button></div></div><div style="overflow:auto;margin-top:16px"><table class="access-table" style="min-width:700px;width:100%"><thead><tr><th>Matrícula</th><th>Nome do estudante</th><th>Turma</th><th>Etapa</th><th>Ano</th></tr></thead><tbody>${rosterListing.students.map(student=>`<tr><td>${esc(student.enrollment)}</td><td>${esc(student.name)}</td><td>${esc(student.className)}</td><td>${esc(student.educationStageLabel||'—')}</td><td>${esc(student.gradeLabel||'—')}</td></tr>`).join('')||`<tr><td colspan="5" style="text-align:center;color:#8a94a6;padding:24px">${rosterQuery?'Nenhum estudante corresponde à busca.':'A lista importada aparecerá aqui.'}</td></tr>`}</tbody></table></div><div style="display:flex;justify-content:space-between;align-items:center;gap:12px;margin-top:14px"><button class="btn outline" onclick="loadRosterPage(${Math.max(1,rosterListing.page-1)})" ${rosterListing.page<=1?'disabled':''}>← Anterior</button><span class="hint">Página ${rosterListing.page} de ${rosterListing.pages}</span><button class="btn outline" onclick="loadRosterPage(${Math.min(rosterListing.pages,rosterListing.page+1)})" ${rosterListing.page>=rosterListing.pages?'disabled':''}>Próxima →</button></div></section>`}
function showRosterFile(){const file=$('#rosterFile')?.files?.[0],status=$('#rosterFileStatus'),button=$('#importRosterButton');if(!file){status.textContent='Escolha um arquivo .xlsx ou .csv de até 25 MB.';button.disabled=true;return}const extension=file.name.toLowerCase().split('.').pop(),valid=['xlsx','csv'].includes(extension),sizeOk=file.size<=25*1024*1024;status.textContent=`${file.name} · ${(file.size/1024/1024).toFixed(2)} MB${!valid?' · formato não aceito (use .xlsx ou .csv)':''}${!sizeOk?' · excede o limite de 25 MB':''}`;button.disabled=!valid||!sizeOk}
async function importStudentRoster(){const file=$('#rosterFile')?.files?.[0],status=$('#rosterUploadStatus');if(!file){if(status)status.textContent='Escolha a planilha no campo acima antes de enviar.';return}const extension=file.name.toLowerCase().split('.').pop();if(!['xlsx','csv'].includes(extension)){if(status)status.textContent='Formato não aceito. Salve a planilha como .xlsx ou .csv e tente novamente.';return}if(file.size>25*1024*1024){if(status)status.textContent='O arquivo excede o limite de 25 MB.';return}const button=$('#importRosterButton');button.disabled=true;button.textContent='Enviando e validando…';if(status)status.textContent='Enviando a planilha ao sistema e conferindo as colunas A, B e C…';try{const response=await fetch('/api/admin/roster/import',{method:'POST',credentials:'same-origin',headers:{'Content-Type':extension==='xlsx'?'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet':'text/csv','X-Roster-Format':extension},body:await file.arrayBuffer()});const result=await response.json();if(response.status===401)throw new Error('Sua sessão da equipe expirou. Entre novamente na área da equipe e repita o envio.');if(!response.ok)throw new Error(result.error||'Não foi possível importar a planilha.');rosterMeta={count:result.count,importedAt:result.importedAt};rosterQuery='';await loadRosterPage(1,'',false);render();const success=$('#rosterUploadStatus');if(success)success.textContent=`Importação concluída: ${result.count} estudantes foram enviados e salvos no sistema.`}catch(error){const message=error.message==='Failed to fetch'?'Não foi possível conectar ao sistema. Confira se o site está aberto pelo endereço http://127.0.0.1:3000 e tente novamente.':error.message;if(status)status.textContent=`A planilha não foi importada. ${message}`}finally{const current=$('#importRosterButton');if(current){current.disabled=!$('#rosterFile')?.files?.[0];current.textContent='Enviar e importar planilha'}}}
function accessAdmin(){const unique=new Set(state.visits.map(v=>`${v.enrollment||v.name}|${v.role}`));return `<div style="display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:16px"><h2 class="section-title" style="margin:0">Registros de atividade</h2><button class="btn danger" onclick="confirmClearVisits()" ${state.visits.length?'':'disabled'}>Excluir registros</button></div><div class="stats"><div class="card stat"><span>Acessos registrados</span><strong>${state.visits.length}</strong></div><div class="card stat"><span>Contas identificadas</span><strong>${unique.size}</strong></div><div class="card stat"><span>Plataformas</span><strong>${state.platforms.length}</strong></div></div><div class="card" style="overflow:auto;padding:7px 18px"><table class="access-table"><thead><tr><th>Matrícula</th><th>Estudante</th><th>Turma</th><th>Perfil</th><th>Plataforma</th><th>Conteúdo</th><th>Entrada</th><th>Saída</th><th>Tempo</th></tr></thead><tbody>${[...state.visits].reverse().map(v=>`<tr><td>${esc(v.enrollment||'—')}</td><td>${esc(v.name)}</td><td>${esc(v.className||'—')}</td><td><span class="badge">${esc(v.role)}</span></td><td>${esc(v.platform)}</td><td>${esc(v.kind)}</td><td>${formatActivityTime(v.openedAt||v.time)}</td><td>${v.exitedAt?formatActivityTime(v.exitedAt):v.id===activeActivity?'Em andamento':'—'}</td><td>${formatDuration(v.durationSeconds)}</td></tr>`).join('')||'<tr><td colspan="9" style="text-align:center;color:#9aa2b1;padding:30px">Os acessos registrados aparecerão aqui.</td></tr>'}</tbody></table></div><p class="hint">A lista de matrícula e turma é mantida no servidor e usada para validar os dados de entrada.</p>`}
function homeView(){if(!state.user)return `<main class="login"><section class="card login-box"><div class="eyebrow">Acesso para responsáveis</div><h1>Acesse os tutoriais da escola</h1><p class="sub">Informe a matrícula e o nome do estudante, exatamente como constam na planilha da equipe administrativa.</p><div class="field"><label for="userEnrollment">Matrícula do estudante (8 dígitos)</label><input id="userEnrollment" type="text" inputmode="numeric" autocomplete="off" maxlength="8" pattern="[0-9]{8}" placeholder="Ex.: 00123456"></div><div class="field"><label for="studentName">Nome do estudante</label><input id="studentName" autocomplete="off" placeholder="Como aparece na lista escolar"></div><button class="btn primary" style="width:100%;margin-top:4px" onclick="enterUser()">Entrar na central →</button><p class="hint">O acesso é liberado somente quando os dados correspondem à lista importada pela equipe administrativa. Os acessos aos tutoriais serão registrados.</p></section></main>`;return `<main class="wrap"><section class="welcome"><div><div class="eyebrow">Central de aprendizagem</div><h1 class="heading home-heading">Olá, ${esc(state.user.name.split(' ')[0])}</h1><p class="sub">Acesse os guias e tutoriais das plataformas utilizadas na escola.</p></div><button class="btn quiet" onclick="logoutUser()">Trocar usuário</button></section><div class="section-title">Plataformas disponíveis <span style="color:#9aa2b1;font-weight:500;font-size:13px">· ${state.platforms.length}</span></div><section class="grid">${state.platforms.length?state.platforms.map(p=>`<article class="card platform user-platform" onclick="openPlatform('${p.id}')">${platformIcon(p)}<h3>${esc(p.name)}</h3><p>${esc(p.summary).slice(0,95)}${p.summary.length>95?'…':''}</p><div class="card-foot"><span>${p.pdfs.length} PDFs · ${p.videos.length} vídeos</span><span class="arrow">Ver tutoriais ↗</span></div></article>`).join(''):'<div class="card empty">Ainda não há plataformas cadastradas.</div>'}</section></main>`}
async function enterUser(){const enrollment=$('#userEnrollment').value.trim(),name=$('#studentName').value.trim().replace(/\s+/g,' '),button=$('.login-box .primary');if(!/^\d{8}$/.test(enrollment)){toast('Digite a matrícula com exatamente 8 números.');return}if(!name){toast('Digite o nome do estudante como aparece na planilha.');return}button.disabled=true;try{const response=await fetch('/api/student/login',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({enrollment,name})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Não foi possível conferir os dados.');state.user=result.student;page='home';render()}catch(error){toast(error.message==='Failed to fetch'?'Não foi possível conectar ao sistema. Tente novamente.':error.message)}finally{if($('.login-box .primary'))$('.login-box .primary').disabled=false}}
function header(){return `<header class="topbar"><div class="brand"><img class="brand-mark" src="assets/colegio-santa-ines.png" alt="Símbolo do Colégio Santa Inês"><div>Colégio Santa Inês<small>CENTRAL DE PLATAFORMAS</small></div></div><div class="navright">${state.admin?'<span class="role-pill">Equipe TE</span>':state.user?`<span class="user-pill">Acesso do responsável · ${esc(state.user.name)}</span>`:''}<button class="menu-toggle" aria-label="Abrir menu" aria-expanded="${menuOpen}" onclick="toggleMenu()"><span></span><span></span><span></span></button></div>${menuOpen?`<nav class="menu-pop"><button onclick="goHome()">⌂ &nbsp;Página inicial</button>${state.admin?`<button onclick="adminTab='platforms';menuOpen=false;render()">▦ &nbsp;Gerenciar plataformas</button><button onclick="adminTab='roster';menuOpen=false;render();loadRosterMeta()">♙ &nbsp;Lista de estudantes</button><button onclick="adminTab='access';menuOpen=false;render();loadActivityRecords()">◷ &nbsp;Registros de acesso</button><button onclick="adminTab='settings';menuOpen=false;render()">✉ &nbsp;Contato de suporte</button><button onclick="logoutAdmin()">↪ &nbsp;Sair da equipe</button>`:`<button onclick="openAdmin()">♙ &nbsp;Área da equipe TE</button>${state.user?`<button onclick="logoutUser()">↪ &nbsp;Trocar usuário</button>`:''}`}</nav>`:''}</header>`}
function createActivity(platform,kind){if(!state.user)return;if(activeActivity)finishActivity();const entry={id:'a'+Date.now()+Math.random().toString(36).slice(2),name:state.user.name,enrollment:state.user.enrollment,className:state.user.className,platform,kind,openedAt:new Date().toISOString(),exitedAt:null};state.visits.push(entry);activeActivity=entry.id;fetch('/api/activities',{method:'POST',credentials:'same-origin',keepalive:true,headers:{'Content-Type':'application/json'},body:JSON.stringify(entry)}).catch(()=>{})}
function accessAdmin(){const unique=new Set(state.visits.map(v=>v.enrollment||v.name));return `<div style="display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:16px"><h2 class="section-title" style="margin:0">Registros de atividade</h2><button class="btn danger" onclick="confirmClearVisits()" ${state.visits.length?'':'disabled'}>Excluir registros</button></div><div class="stats"><div class="card stat"><span>Acessos registrados</span><strong>${state.visits.length}</strong></div><div class="card stat"><span>Estudantes identificados</span><strong>${unique.size}</strong></div><div class="card stat"><span>Plataformas</span><strong>${state.platforms.length}</strong></div></div><div class="card" style="overflow:auto;padding:7px 18px"><table class="access-table"><thead><tr><th>Matrícula</th><th>Estudante</th><th>Turma</th><th>Plataforma</th><th>Conteúdo</th><th>Entrada</th><th>Saída</th><th>Tempo</th></tr></thead><tbody>${[...state.visits].reverse().map(v=>`<tr><td>${esc(v.enrollment||'—')}</td><td>${esc(v.name)}</td><td>${esc(v.className||'—')}</td><td>${esc(v.platform)}</td><td>${esc(v.kind)}</td><td>${formatActivityTime(v.openedAt||v.time)}</td><td>${v.exitedAt?formatActivityTime(v.exitedAt):v.id===activeActivity?'Em andamento':'—'}</td><td>${formatDuration(v.durationSeconds)}</td></tr>`).join('')||'<tr><td colspan="8" style="text-align:center;color:#9aa2b1;padding:30px">Os acessos registrados aparecerão aqui.</td></tr>'}</tbody></table></div><p class="hint">A identificação é feita pela matrícula e pelo nome do estudante cadastrados na planilha. O acesso é considerado de responsável.</p>`}
const GRADE_GROUPS=[{stage:'anos-iniciais',label:'Anos Iniciais',grades:[1,2,3,4,5]},{stage:'anos-finais',label:'Anos Finais',grades:[6,7,8,9]},{stage:'ensino-medio',label:'Ensino Médio',grades:[1,2,3]}];
const GRADE_OPTIONS=GRADE_GROUPS.flatMap(group=>group.grades.map(grade=>({id:`${group.stage}-${grade}`,stage:group.stage,label:`${grade}º ano${group.stage==='ensino-medio'?' do Ensino Médio':''}`})));
function gradeIdForClass(value){const code=String(value||'').replace(/\s+/g,'').toUpperCase();if(/^[1-5][1-9]$/.test(code))return`anos-iniciais-${Number(code[0])}`;if(/^[6-9][1-9]$/.test(code))return`anos-finais-${Number(code[0])}`;if(/^[1-3][A-Z]$/.test(code))return`ensino-medio-${Number(code[0])}`;return''}
function legacyGrades(platform){if(Array.isArray(platform?.grades)&&platform.grades.length)return platform.grades;if(Array.isArray(platform?.stages)&&platform.stages.length)return GRADE_OPTIONS.filter(option=>platform.stages.includes(option.stage)).map(option=>option.id);return GRADE_OPTIONS.map(option=>option.id)}
const editPlatformOriginal=editPlatform;
editPlatform=function(id){const existing=state.platforms.find(platform=>platform.id===id),selectedGrades=legacyGrades(existing);editPlatformOriginal(id);const form=$('.formgrid');if(!form)return;const field=document.createElement('div');field.className='field full';field.innerHTML=`<label>Séries que verão esta plataforma</label><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,210px),1fr));gap:12px;margin-top:10px">${GRADE_GROUPS.map(group=>`<fieldset style="border:1px solid var(--line);border-radius:12px;padding:12px;min-width:0"><legend style="font-weight:700;color:var(--ink);padding:0 5px">${group.label}</legend><div style="display:grid;gap:9px">${GRADE_OPTIONS.filter(option=>option.stage===group.stage).map(option=>`<label style="display:flex;align-items:center;gap:10px;font-size:16px"><input type="checkbox" name="platformGrade" style="width:20px;height:20px;flex:none" value="${option.id}" ${selectedGrades.includes(option.id)?'checked':''}>${option.label}</label>`).join('')}</div></fieldset>`).join('')}</div><small>A turma da planilha determina automaticamente a série. Marque todas as séries para as quais este tutorial deve aparecer.</small>`;form.append(field)};
const savePlatformOriginal=savePlatform;
savePlatform=async function(id,editing){const grades=[...document.querySelectorAll('input[name="platformGrade"]:checked')].map(input=>input.value);if(!grades.length){toast('Selecione ao menos uma série.');return}const persistOriginal=persistSiteContent;persistSiteContent=async function(){const platform=state.platforms.find(item=>item.id===id);if(platform){platform.grades=grades;platform.stages=[...new Set(GRADE_OPTIONS.filter(option=>grades.includes(option.id)).map(option=>option.stage))]}return persistOriginal()};try{await savePlatformOriginal(id,editing)}finally{persistSiteContent=persistOriginal}};
const homeViewOriginal=homeView;
homeView=function(){if(!state.user)return homeViewOriginal();const gradeId=state.user.gradeId||gradeIdForClass(state.user.className),stage=state.user.educationStage||((gradeId||'').startsWith('anos-iniciais-')?'anos-iniciais':(gradeId||'').startsWith('anos-finais-')?'anos-finais':(gradeId||'').startsWith('ensino-medio-')?'ensino-medio':''),allPlatforms=state.platforms;state.platforms=allPlatforms.filter(platform=>{if(!gradeId)return true;if(Array.isArray(platform.grades)&&platform.grades.length)return platform.grades.includes(gradeId);return !stage||!Array.isArray(platform.stages)||!platform.stages.length||platform.stages.includes(stage)});let markup=homeViewOriginal();state.platforms=allPlatforms;if(gradeId&&!state.platforms.filter(platform=>Array.isArray(platform.grades)&&platform.grades.length?platform.grades.includes(gradeId):!stage||!Array.isArray(platform.stages)||!platform.stages.length||platform.stages.includes(stage)).length&&allPlatforms.length){const label=GRADE_OPTIONS.find(option=>option.id===gradeId)?.label||'sua série';markup=markup.replace('Ainda não há plataformas cadastradas.','Nenhuma plataforma está disponível para '+label+'.')}return markup};
let pendingBrandIcons={play:'',apple:''};
function storeImagePreview(value,label){return value?`<img src="${esc(value)}" alt="Prévia do ícone ${label}">`:`<span>Cole uma imagem com Ctrl+V ou selecione um arquivo</span>`}
function processBrandIcon(which,file){if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>5*1024*1024){toast('Use uma imagem PNG, JPG ou WebP de até 5 MB.');return}const reader=new FileReader();reader.onload=()=>{const image=new Image();image.onload=()=>{const canvas=document.createElement('canvas'),scale=Math.min(1,512/Math.max(image.width,image.height));canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);pendingBrandIcons[which]=canvas.toDataURL('image/png');const zone=$(`#brand${which==='play'?'Play':'Apple'}Preview`);if(zone)zone.innerHTML=storeImagePreview(pendingBrandIcons[which],which==='play'?'Google Play':'App Store')};image.src=reader.result};reader.readAsDataURL(file)}
function loadBrandIcon(which,input){processBrandIcon(which,input.files?.[0])}
document.addEventListener('paste',event=>{const active=document.activeElement,which=active?.id==='brandPlayPreview'?'play':active?.id==='brandApplePreview'?'apple':'';if(!which)return;const item=[...(event.clipboardData?.items||[])].find(entry=>entry.type.startsWith('image/'));if(!item){toast('Copie uma imagem antes de colar o ícone.');return}event.preventDefault();processBrandIcon(which,item.getAsFile())});
const settingsAdminStoreOriginal=settingsAdmin;
settingsAdmin=function(){pendingBrandIcons={...storeIcons};const markup=settingsAdminStoreOriginal(),position=markup.lastIndexOf('</div>'),editor=`<section class="brand-icon-settings"><h2 class="section-title">Ícones das lojas</h2><p class="sub" style="font-size:14px;margin-bottom:14px">Configure cada imagem uma única vez. Ela será reutilizada nos links de todas as plataformas.</p><div class="store-editor-grid"><div class="store-editor-item"><strong>Google Play</strong><div id="brandPlayPreview" class="store-paste-zone" tabindex="0">${storeImagePreview(pendingBrandIcons.play,'Google Play')}</div><input type="file" accept="image/png,image/jpeg,image/webp" aria-label="Imagem da Google Play" onchange="loadBrandIcon('play',this)"></div><div class="store-editor-item"><strong>App Store</strong><div id="brandApplePreview" class="store-paste-zone" tabindex="0">${storeImagePreview(pendingBrandIcons.apple,'App Store')}</div><input type="file" accept="image/png,image/jpeg,image/webp" aria-label="Imagem da App Store" onchange="loadBrandIcon('apple',this)"></div></div><button class="btn primary" style="margin-top:14px" onclick="saveBrandIcons()">Salvar ícones</button></section>`;return markup.slice(0,position)+editor+markup.slice(position)};
async function saveBrandIcons(){const previous=storeIcons;storeIcons={...pendingBrandIcons};try{await persistSiteContent();render();toast('Ícones das lojas salvos para todas as plataformas.')}catch(error){storeIcons=previous;toast(error.message||'Não foi possível salvar os ícones.') }}
const editPlatformLinksOriginal=editPlatform;
editPlatform=function(id){editPlatformLinksOriginal(id);const platform=state.platforms.find(item=>item.id===id),form=$('.formgrid');if(!form)return;const summaryLabel=[...form.querySelectorAll('label')].find(label=>label.htmlFor==='pSummary'||label.textContent.includes('Texto explicativo'));if(summaryLabel)summaryLabel.textContent='Descrição da plataforma';const summary=$('#pSummary');if(summary)summary.placeholder='Apresente a plataforma e explique para que ela é usada na escola.';const field=document.createElement('div');field.className='field full';field.innerHTML=`<label>Links para acessar ou baixar o aplicativo</label><div class="store-editor-grid"><div class="store-editor-item"><strong>Google Play</strong><input id="platformPlayLink" type="url" inputmode="url" placeholder="Link da Google Play" value="${esc(platform?.playStoreUrl||'')}"></div><div class="store-editor-item"><strong>App Store</strong><input id="platformAppleLink" type="url" inputmode="url" placeholder="Link da App Store" value="${esc(platform?.appStoreUrl||'')}"></div><div class="store-editor-item store-web-item"><strong>Acesso pelo navegador</strong><div class="store-browser-symbol" aria-hidden="true">↗</div><input id="platformWebLink" type="url" inputmode="url" placeholder="Link para acessar pelo navegador" value="${esc(platform?.webUrl||'')}"></div></div><small>Preencha somente os links disponíveis. Os botões sem link não aparecem para as famílias. Os ícones são configurados uma vez nas definições da Equipe TE.</small>`;form.append(field)};
const savePlatformLinksOriginal=savePlatform;
savePlatform=async function(id,editing){const links={playStoreUrl:$('#platformPlayLink')?.value.trim()||'',appStoreUrl:$('#platformAppleLink')?.value.trim()||'',webUrl:$('#platformWebLink')?.value.trim()||''};for(const url of Object.values(links)){if(url&&!/^https?:\/\//i.test(url)){toast('Os links devem começar com https:// ou http://.');return}}const persistOriginal=persistSiteContent;persistSiteContent=async function(){const platform=state.platforms.find(item=>item.id===id);if(platform)Object.assign(platform,links);return persistOriginal()};try{await savePlatformLinksOriginal(id,editing)}finally{persistSiteContent=persistOriginal}};
const detailViewAccessOriginal=detailView;
detailView=function(){const markup=detailViewAccessOriginal(),platform=state.platforms.find(item=>item.id===selected);if(!platform)return markup;const description=`<div class="info-box"><strong>Descrição da plataforma</strong>${esc(platform.summary)}</div>`;const playIcon=storeIcons.play?`<img class="store-mark store-custom-icon" src="${esc(storeIcons.play)}" alt="">`:'<span class="store-mark play-mark" aria-hidden="true">▶</span>',appleIcon=storeIcons.apple?`<img class="store-mark store-custom-icon" src="${esc(storeIcons.apple)}" alt="">`:'<svg class="store-mark apple-mark" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3v18M5 7l14 10M19 7L5 17" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/></svg>';const links=[{url:platform.playStoreUrl,label:'Google Play',icon:playIcon},{url:platform.appStoreUrl,label:'App Store',icon:appleIcon},{url:platform.webUrl,label:'Acessar pelo navegador',icon:'<span class="store-mark web-mark" aria-hidden="true">↗</span>'}];const access=`<section class="platform-access-section"><h2>Como acessar:</h2><div class="platform-access">${links.map(link=>link.url?`<a class="access-link" href="${esc(link.url)}" target="_blank" rel="noopener noreferrer">${link.icon}<span>${link.label}</span></a>`:'<div class="access-slot" aria-hidden="true"></div>').join('')}</div></section>`;return markup.replace(/<div class="info-box"><strong>Como acessar<\/strong>[\s\S]*?<\/div>/,description+access)};
const accessStyle=document.createElement('style');accessStyle.textContent='.platform-access-section{margin-top:18px}.platform-access-section h2{font:700 20px Manrope,sans-serif;margin:0 0 12px}.platform-access{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.access-link,.access-slot{min-width:0;min-height:100px}.access-link{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;padding:12px 8px;text-align:center;text-decoration:none;background:var(--blue);color:#fff;border:1px solid var(--blue);border-radius:0 17px 0 17px;font-size:14px;font-weight:700;overflow-wrap:anywhere}.access-link:hover{background:#173f7d}.store-mark{display:block;width:26px;height:26px;font-size:26px;line-height:1}.store-custom-icon{object-fit:contain;background:#fff;border-radius:5px}.play-mark{color:#68e3ac}.apple-mark{color:#fff}.web-mark{font-size:31px}.access-slot{visibility:hidden}.store-editor-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.brand-icon-settings .store-editor-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.store-editor-item{display:grid;gap:9px;min-width:0;overflow:hidden;padding:12px;border:1px solid var(--line);border-radius:12px}.store-editor-item strong{font-size:14px}.store-editor-item input[type=file]{width:100%;min-width:0;max-width:100%;box-sizing:border-box;font-size:11px}.store-editor-item input[type=url]{width:100%;min-width:0;border:1px solid #dfe3ec;border-radius:9px;padding:11px;font:inherit;font-size:14px}.store-paste-zone{display:grid;width:100%;min-width:0;box-sizing:border-box;height:84px;border:1px dashed #89a9d3;border-radius:0 14px 0 14px;background:#f4f8ff;place-items:center;text-align:center;overflow:hidden;padding:8px;color:var(--blue);font-size:12px;cursor:text}.store-paste-zone img{display:block;width:auto;max-width:100%;max-height:68px;object-fit:contain}.store-browser-symbol{height:84px;display:grid;place-items:center;color:var(--blue);font-size:36px}@media(max-width:620px){.brand-icon-settings .store-editor-grid{grid-template-columns:1fr}.store-editor-grid{grid-template-columns:1fr}.platform-access{gap:7px}.access-link,.access-slot{min-height:88px}.access-link{padding:9px 5px;font-size:12px}.store-mark{width:22px;height:22px;font-size:22px}}';document.head.append(accessStyle);
const platformPasteStyle=document.createElement('style');platformPasteStyle.textContent='#platformPaste.has-image{display:inline-grid;width:max-content;max-width:100%;height:auto;min-height:0;place-items:center;padding:8px;border-style:solid;background:#f4f8ff;overflow:visible}#platformPaste.has-image img{display:block;width:auto;height:auto;max-width:100%;max-height:360px;object-fit:contain;border-radius:8px}';document.head.append(platformPasteStyle);
let yearPlan=null,yearPlanLoading=false,yearPlanError='',yearSearch='',yearPage=1,yearChecked={},yearDestinations={},studentFormOriginal='';
const annualApi=async(url,options={})=>{const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),30000);let response;try{response=await fetch(url,{credentials:'same-origin',...options,signal:controller.signal,headers:{'Content-Type':'application/json',...(options.headers||{})}})}catch(error){if(error.name==='AbortError')throw new Error('O servidor demorou mais de 30 segundos para responder. Confira se está aberto e tente carregar novamente.');throw new Error('Não foi possível conectar ao servidor. Confira se está aberto e tente novamente.')}finally{clearTimeout(timeout)}const result=await response.json().catch(()=>({}));if(response.status===401)throw new Error('A sessão da Equipe TE expirou. Entre novamente.');if(!response.ok)throw new Error(result.error||'Não foi possível concluir a operação.');return result};
adminView=function(){return `<main class="wrap"><div class="welcome"><div><div class="eyebrow">Painel de gestão</div><h1 class="heading">Área da equipe TE</h1><p class="sub">Gerencie plataformas, lista de estudantes e acompanhe o acesso aos tutoriais.</p></div></div><nav class="adminbar"><button class="tab ${adminTab==='platforms'?'active':''}" onclick="adminTab='platforms';render()">Plataformas</button><button class="tab ${adminTab==='roster'?'active':''}" onclick="adminTab='roster';render();loadRosterMeta()">Lista de estudantes</button><button class="tab ${adminTab==='year'?'active':''}" onclick="adminTab='year';render();loadYearPlan()">Ano letivo</button><button class="tab ${adminTab==='access'?'active':''}" onclick="adminTab='access';render();loadActivityRecords()">Acessos</button><button class="tab ${adminTab==='settings'?'active':''}" onclick="adminTab='settings';render()">Contato de suporte</button></nav>${adminTab==='platforms'?platformAdmin():adminTab==='roster'?rosterAdmin():adminTab==='year'?yearAdmin():adminTab==='access'?accessAdmin():settingsAdmin()}</main>`};
function rosterAdmin(){const first=rosterListing.total?(rosterListing.page-1)*rosterListing.pageSize+1:0,last=Math.min(rosterListing.page*rosterListing.pageSize,rosterListing.total);return `<section class="card" style="max-width:900px"><h2 class="section-title" style="margin-top:0">Importar lista de estudantes</h2><p class="sub" style="font-size:15px;margin-bottom:16px">A importação substitui a lista atual. Faça-a quando receber a planilha oficial da escola.</p><div class="card" style="background:#f5f8fd;margin-bottom:20px"><strong>Colunas esperadas</strong><p style="margin:8px 0 0;line-height:1.7">A · Matrícula (8 dígitos) &nbsp; B · Nome do estudante &nbsp; C · Turma</p><small>A primeira linha pode conter os títulos das colunas. Use Excel (.xlsx) ou CSV.</small></div><div class="field"><label for="rosterFile">Planilha Excel (.xlsx) ou CSV exportado do Excel</label><input id="rosterFile" type="file" accept=".xlsx,.csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,text/csv" onchange="showRosterFile()"><div id="rosterFileStatus" class="hint" style="margin-top:8px">Escolha um arquivo .xlsx ou .csv de até 25 MB.</div></div><button id="importRosterButton" class="btn primary" style="margin-top:16px" onclick="importStudentRoster()" disabled>Enviar e importar planilha</button><p id="rosterUploadStatus" class="hint" role="status" aria-live="polite" style="margin-top:14px"></p><div class="hint" style="margin-top:22px">${rosterMeta.count?`Lista atual: ${rosterMeta.count} estudantes. Atualizada em ${formatActivityTime(rosterMeta.importedAt)}.`:'Nenhuma lista de estudantes foi importada ainda.'}</div></section><section class="card student-editor" style="margin-top:20px"><h2 class="section-title" style="margin:0 0 6px">Adicionar ou editar estudante</h2><p class="hint" style="margin:0 0 16px">Cadastre um estudante fora da planilha ou corrija matrícula, nome e turma.</p><input id="studentOriginalEnrollment" type="hidden" value="${esc(studentFormOriginal)}"><div class="student-form-grid"><label>Matrícula<input id="studentEditEnrollment" inputmode="numeric" maxlength="8" placeholder="8 dígitos"></label><label>Nome do estudante<input id="studentEditName" autocomplete="off" placeholder="Nome completo"></label><label>Turma<input id="studentEditClass" list="currentClassOptions" placeholder="Ex.: 63 ou 1A"><datalist id="currentClassOptions">${[...new Set(rosterListing.students.map(s=>s.className))].sort().map(value=>`<option value="${esc(value)}">`).join('')}</datalist></label></div><div class="student-form-actions"><button class="btn primary" onclick="saveRosterStudent()">Salvar estudante</button><button class="btn outline" onclick="clearStudentForm()">Limpar</button><span id="studentFormStatus" class="hint" role="status"></span></div></section><section class="card" style="margin-top:20px"><div class="student-list-head"><div><h2 class="section-title" style="margin:0 0 5px">Estudantes cadastrados</h2><p class="hint" style="margin:0">${rosterListing.total} estudante${rosterListing.total===1?'':'s'} · ${rosterLoading?'Carregando…':rosterListing.total?`Exibindo ${first}–${last}`:'Nenhum estudante cadastrado'}</p></div><div class="student-list-actions"><div class="student-search"><input id="rosterSearch" type="search" value="${esc(rosterQuery)}" placeholder="Buscar matrícula, nome ou turma" aria-label="Buscar estudantes" onkeydown="if(event.key==='Enter')searchRoster()"><button class="btn primary" onclick="searchRoster()">Buscar</button></div><button class="btn danger" onclick="openClearRosterConfirm()" ${rosterMeta.count?'':'disabled'}>Remover todos os estudantes</button></div></div><div style="overflow:auto;margin-top:16px"><table class="access-table student-table"><thead><tr><th>Matrícula</th><th>Nome do estudante</th><th>Turma</th><th>Etapa</th><th>Ano</th><th>Ação</th></tr></thead><tbody>${rosterListing.students.map(student=>`<tr><td>${esc(student.enrollment)}</td><td>${esc(student.name)}</td><td>${esc(student.className)}</td><td>${esc(student.educationStageLabel||'—')}</td><td>${esc(student.gradeLabel||'—')}</td><td><button class="btn outline" onclick="editRosterStudent('${esc(student.enrollment)}')">Editar</button></td></tr>`).join('')||`<tr><td colspan="6" style="text-align:center;color:#8a94a6;padding:24px">${rosterQuery?'Nenhum estudante corresponde à busca.':'A lista importada aparecerá aqui.'}</td></tr>`}</tbody></table></div><div class="student-pagination"><button class="btn outline" onclick="loadRosterPage(${Math.max(1,rosterListing.page-1)})" ${rosterListing.page<=1?'disabled':''}>← Anterior</button><span class="hint">Página ${rosterListing.page} de ${rosterListing.pages}</span><button class="btn outline" onclick="loadRosterPage(${Math.min(rosterListing.pages,rosterListing.page+1)})" ${rosterListing.page>=rosterListing.pages?'disabled':''}>Próxima →</button></div></section>`}
function editRosterStudent(enrollment){const student=rosterListing.students.find(item=>item.enrollment===enrollment);if(!student)return;studentFormOriginal=student.enrollment;$('#studentOriginalEnrollment').value=student.enrollment;$('#studentEditEnrollment').value=student.enrollment;$('#studentEditName').value=student.name;$('#studentEditClass').value=student.className;$('#studentFormStatus').textContent=`Editando ${student.name}`;document.querySelector('.student-editor')?.scrollIntoView({behavior:'smooth',block:'center'})}
function clearStudentForm(){studentFormOriginal='';$('#studentOriginalEnrollment').value='';$('#studentEditEnrollment').value='';$('#studentEditName').value='';$('#studentEditClass').value='';$('#studentFormStatus').textContent=''}
async function saveRosterStudent(){const enrollment=$('#studentEditEnrollment').value.trim(),name=$('#studentEditName').value.trim().replace(/\s+/g,' '),className=$('#studentEditClass').value.trim().toUpperCase(),originalEnrollment=$('#studentOriginalEnrollment').value,status=$('#studentFormStatus');if(!/^\d{8}$/.test(enrollment)){status.textContent='A matrícula precisa ter exatamente 8 números.';return}if(!name||!className){status.textContent='Preencha nome e turma.';return}try{const result=await annualApi('/api/admin/roster/student',{method:'POST',body:JSON.stringify({enrollment,name,className,originalEnrollment})});studentFormOriginal='';rosterMeta={count:result.count,importedAt:result.importedAt};const message=originalEnrollment?'Estudante atualizado.':'Estudante adicionado.';await loadRosterPage(1,rosterQuery,false);render();$('#studentFormStatus').textContent=message}catch(error){status.textContent=error.message}}
async function loadYearPlan(){yearSearch='';yearPage=1;yearPlan=null;yearPlanLoading=true;yearPlanError='';if(state.admin&&adminTab==='year')render();try{yearPlan=await annualApi('/api/admin/roster/year-plan');yearChecked=Object.fromEntries(yearPlan.students.map(s=>[s.enrollment,true]));yearDestinations=Object.fromEntries(yearPlan.students.map(s=>[s.enrollment,s.suggestedClass]))}catch(error){yearPlanError=error.message;toast(error.message)}finally{yearPlanLoading=false;if(state.admin&&adminTab==='year')render()}}
function yearClassSort(a,b){const ax=/^\d/.test(a)?Number(a[0]):0,bx=/^\d/.test(b)?Number(b[0]):0;return ax-bx||a.localeCompare(b,'pt-BR',{numeric:true,sensitivity:'base'})}
function yearAdmin(){if(!yearPlan){if(yearPlanLoading)return `<section class="card" style="max-width:900px" role="status" aria-live="polite">Carregando estudantes e turmas…</section>`;if(yearPlanError)return `<section class="card annual-load-error" role="alert" style="max-width:900px"><h2>Não foi possível carregar estudantes e turmas</h2><p>${esc(yearPlanError)}</p><button class="btn primary" onclick="yearPlanError.includes('sessão da Equipe TE expirou')?(state.admin=false,page='login',render()):loadYearPlan()">${yearPlanError.includes('sessão da Equipe TE expirou')?'Entrar novamente':'Tentar novamente'}</button></section>`;return `<section class="card" style="max-width:900px"><p>Os dados ainda não foram carregados.</p><button class="btn primary" onclick="loadYearPlan()">Carregar estudantes e turmas</button></section>`}const filtered=yearPlan.students.filter(s=>normalizeText(`${s.enrollment} ${s.name} ${s.className} ${s.gradeLabel} ${yearDestinations[s.enrollment]||''}`).includes(normalizeText(yearSearch))),pages=Math.max(1,Math.ceil(filtered.length/100)),page=Math.min(yearPage,pages),visible=filtered.slice((page-1)*100,page*100),classes=[...yearPlan.availableClasses].sort(yearClassSort),failed=visible.filter(s=>yearChecked[s.enrollment]&&!classes.includes(yearDestinations[s.enrollment]));return `<section class="card annual-intro"><div class="eyebrow">Organização da lista escolar</div><h2>Preparar o ano letivo de ${yearPlan.targetYear}</h2><p class="sub">A lista atual é de ${yearPlan.currentYear}. Todos os estudantes começam selecionados e recebem uma turma sugerida. Revise as turmas existentes e ajuste as exceções antes de aplicar.</p><div class="annual-rule-grid"><div><strong>1º–5º ano</strong><span>Anos Iniciais</span></div><div><strong>6º–9º ano</strong><span>Anos Finais</span></div><div><strong>Ensino Médio</strong><span>1A–3Z</span></div></div><p class="hint">A passagem atualiza o cadastro existente pela matrícula: substitui a turma e mantém uma única lista ativa, sem duplicar estudantes ou manter anos simultâneos. As passagens para o 3º ano do Ensino Médio permanecem no 3º por segurança; revise esses casos individualmente.</p></section><section class="card annual-classes"><div class="annual-section-head"><div><h2 class="section-title" style="margin:0 0 5px">Turmas existentes em ${yearPlan.targetYear}</h2><p class="hint" style="margin:0">Confirme quais turmas estarão abertas. As sugestões foram geradas a partir das turmas atuais.</p></div><button class="btn primary" onclick="saveYearClasses()">Salvar turmas</button></div><div class="class-chip-list">${classes.map(value=>`<span class="class-chip">${esc(value)}<button aria-label="Remover turma ${esc(value)}" onclick="removeYearClass('${esc(value)}')">×</button></span>`).join('')||'<span class="hint">Nenhuma turma cadastrada ainda.</span>'}</div><div class="class-add-row"><label>Adicionar turma<input id="newYearClass" list="yearClassOptions" placeholder="Ex.: 82 ou 1A" onkeydown="if(event.key==='Enter'){event.preventDefault();addYearClass()}"><datalist id="yearClassOptions">${[...new Set(yearPlan.students.map(s=>s.suggestedClass))].sort(yearClassSort).map(value=>`<option value="${esc(value)}">`).join('')}</datalist></label><button class="btn outline" onclick="addYearClass()">Adicionar turma</button></div><div id="yearClassStatus" class="hint" role="status"></div></section><section class="card annual-students"><div class="annual-section-head"><div><h2 class="section-title" style="margin:0 0 5px">Revisar estudantes</h2><p class="hint" style="margin:0">${filtered.length} estudante${filtered.length===1?'':'s'} · ${Object.values(yearChecked).filter(Boolean).length} selecionados para avançar</p></div><div class="annual-search"><input id="yearSearch" type="search" value="${esc(yearSearch)}" placeholder="Buscar por nome, matrícula ou turma" onkeydown="if(event.key==='Enter')searchYearStudents()"><button class="btn primary" onclick="searchYearStudents()">Buscar</button></div></div><div class="annual-bulk"><button class="btn outline" onclick="setYearChecks(true)">Selecionar todos</button><button class="btn outline" onclick="setYearChecks(false)">Desmarcar resultados</button><span>Desmarcados permanecem na turma atual. Para mover alguém para outra turma, mantenha selecionado e altere o destino.</span></div><div class="annual-table-scroll"><table class="access-table annual-table"><thead><tr><th>Avançar</th><th>Estudante</th><th>Turma atual</th><th>Série</th><th>Turma em ${yearPlan.targetYear}</th></tr></thead><tbody>${visible.map(s=>{const checked=!!yearChecked[s.enrollment],destination=yearDestinations[s.enrollment]||s.suggestedClass,valid=classes.includes(destination);return `<tr class="${checked&&!valid?'invalid-class':''}"><td><input type="checkbox" aria-label="Avançar ${esc(s.name)}" ${checked?'checked':''} onchange="setYearStudent('${esc(s.enrollment)}',this.checked)"></td><td><strong>${esc(s.name)}</strong><small>${esc(s.enrollment)}</small></td><td>${esc(s.className)}</td><td>${esc(s.gradeLabel||'—')}</td><td><input class="year-destination" list="yearClassOptions" aria-label="Turma de destino para ${esc(s.name)}" value="${esc(destination)}" ${checked?'':'disabled'} onchange="setYearDestination('${esc(s.enrollment)}',this.value)" oninput="setYearDestination('${esc(s.enrollment)}',this.value)"></td></tr>`}).join('')||'<tr><td colspan="5" class="annual-empty">Nenhum estudante encontrado.</td></tr>'}</tbody></table></div><div class="student-pagination"><button class="btn outline" onclick="changeYearPage(${Math.max(1,page-1)})" ${page<=1?'disabled':''}>← Anterior</button><span class="hint">Página ${page} de ${pages}</span><button class="btn outline" onclick="changeYearPage(${Math.min(pages,page+1)})" ${page>=pages?'disabled':''}>Próxima →</button></div><div class="annual-confirm-row"><span class="${failed.length?'annual-error':'hint'}">${failed.length?`${failed.length} destino(s) selecionado(s) ainda não constam na lista de turmas existentes.`:'Confira a seleção e cada exceção antes de aplicar.'}</span><button class="btn primary" onclick="openYearConfirm()" ${failed.length||!yearPlan.students.length?'disabled':''}>Confirmar novo ano letivo</button></div></section>`}
function normalizeText(value){return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()}
function addYearClass(){const input=$('#newYearClass'),value=input.value.trim().toUpperCase(),status=$('#yearClassStatus');try{const normalized=normalizeClass(value);if(yearPlan.availableClasses.includes(normalized)){status.textContent=`A turma ${normalized} já está cadastrada.`;return}yearPlan.availableClasses.push(normalized);yearPlan.availableClasses.sort(yearClassSort);input.value='';render();$('#yearClassStatus').textContent=`Turma ${normalized} incluída. Salve a lista de turmas.`}catch(error){status.textContent=error.message}}
function removeYearClass(value){yearPlan.availableClasses=yearPlan.availableClasses.filter(item=>item!==value);render();$('#yearClassStatus').textContent=`Turma ${value} removida da lista. Destinos associados ficarão sinalizados até serem ajustados.`}
function normalizeClass(value){const code=String(value||'').trim().replace(/\s+/g,'').toUpperCase();if(!/^[1-9][1-9]$/.test(code)&&!(/^[1-3][A-Z]$/.test(code)))throw new Error('Use turmas de 11 a 99 (sem zero) ou 1A a 3Z.');return code}
async function saveYearClasses(){const status=$('#yearClassStatus');try{const result=await annualApi('/api/admin/roster/year-plan/classes',{method:'PUT',body:JSON.stringify({targetYear:yearPlan.targetYear,expectedImportedAt:yearPlan.importedAt,availableClasses:yearPlan.availableClasses})});yearPlan.availableClasses=result.availableClasses;yearPlan.importedAt=result.importedAt;status.textContent=`Turmas salvas para ${result.targetYear}. Revise as destinações e confirme quando estiver pronto.`;render()}catch(error){status.textContent=error.message}}
function setYearStudent(enrollment,checked){yearChecked[enrollment]=checked;render()}
function setYearDestination(enrollment,value){yearDestinations[enrollment]=String(value||'').trim().toUpperCase();const row=[...document.querySelectorAll('.annual-table tbody tr')].find(item=>item.querySelector('input[type=checkbox]')?.getAttribute('aria-label')===`Avançar ${yearPlan.students.find(s=>s.enrollment===enrollment)?.name}`);if(row)row.classList.toggle('invalid-class',!!yearChecked[enrollment]&&!yearPlan.availableClasses.includes(yearDestinations[enrollment]))}
function setYearChecks(checked){const query=normalizeText(yearSearch),targets=yearPlan.students.filter(s=>!query||normalizeText(`${s.enrollment} ${s.name} ${s.className} ${s.gradeLabel} ${yearDestinations[s.enrollment]||''}`).includes(query));for(const student of targets)yearChecked[student.enrollment]=checked;render()}
function searchYearStudents(){yearSearch=$('#yearSearch')?.value.trim()||'';yearPage=1;render()}
function changeYearPage(page){yearSearch=$('#yearSearch')?.value.trim()??yearSearch;yearPage=page;render()}
function openYearConfirm(){const selected=yearPlan.students.filter(s=>yearChecked[s.enrollment]);const wrong=selected.filter(s=>!yearPlan.availableClasses.includes(yearDestinations[s.enrollment]||s.suggestedClass));if(!selected.length){toast('Selecione pelo menos um estudante para avançar.');return}if(wrong.length){toast('Ajuste os destinos que não estão na lista de turmas existentes.');return}$('#modal-root').innerHTML=`<div class="modal-back" role="presentation"><section class="modal annual-confirm-modal" role="dialog" aria-modal="true" aria-labelledby="annualConfirmTitle"><h2 id="annualConfirmTitle">Confirmar ano letivo ${yearPlan.targetYear}</h2><p>Serão atualizadas ${selected.length} matrículas nos próprios cadastros: cada estudante continuará com uma única matrícula, agora associada à nova turma. ${yearPlan.students.length-selected.length} estudantes desmarcados permanecem na turma atual. Não será criado um segundo registro para o mesmo estudante.</p><label>Para concluir, digite <strong>CONFIRMAR</strong><input id="annualConfirmText" autocomplete="off" placeholder="CONFIRMAR" oninput="$('#applyYearButton').disabled=this.value.trim()!=='CONFIRMAR'"></label><div class="modal-actions"><button class="btn outline" onclick="$('#modal-root').innerHTML=''">Voltar</button><button id="applyYearButton" class="btn primary" onclick="applyYearTransition()" disabled>Aplicar passagem</button></div></section></div>`}
async function applyYearTransition(){const button=$('#applyYearButton');if(!button||$('#annualConfirmText').value.trim()!=='CONFIRMAR')return;button.disabled=true;button.textContent='Aplicando…';try{const promoteEnrollments=yearPlan.students.filter(s=>yearChecked[s.enrollment]).map(s=>s.enrollment),placements=Object.fromEntries(promoteEnrollments.map(id=>[id,yearDestinations[id]]));const result=await annualApi('/api/admin/roster/year-plan/apply',{method:'POST',body:JSON.stringify({targetYear:yearPlan.targetYear,expectedImportedAt:yearPlan.importedAt,promoteEnrollments,placements})});$('#modal-root').innerHTML='';rosterMeta={count:result.count,importedAt:result.importedAt};yearPlan=null;toast(`Ano letivo ${result.academicYear} aplicado. ${result.promoted} estudantes avançaram.`);await loadRosterMeta();if(state.admin&&adminTab==='year')await loadYearPlan()}catch(error){button.disabled=false;button.textContent='Aplicar passagem';toast(error.message)}}
function openClearRosterConfirm(){const count=Number(rosterMeta.count)||0;if(!count){toast('Não há estudantes cadastrados para remover.');return}$('#modal-root').innerHTML=`<div class="modal-back" role="presentation"><section class="modal annual-confirm-modal" role="dialog" aria-modal="true" aria-labelledby="clearRosterTitle"><h2 id="clearRosterTitle">Remover todos os estudantes?</h2><p>Esta ação removerá os ${count} estudantes da lista ativa e impedirá novos acessos até que uma planilha seja importada ou os cadastros sejam refeitos. Os registros de atividade serão preservados. Esta ação não pode ser desfeita.</p><label>Para confirmar, digite <strong>CONFIRMAR</strong><input id="clearRosterText" autocomplete="off" placeholder="CONFIRMAR" oninput="$('#clearRosterButton').disabled=this.value!=='CONFIRMAR'"></label><div class="modal-actions"><button class="btn outline" onclick="$('#modal-root').innerHTML=''">Cancelar</button><button id="clearRosterButton" class="btn danger" onclick="deleteAllStudents()" disabled>Remover estudantes</button></div></section></div>`;$('#clearRosterText').focus()}
async function deleteAllStudents(){const input=$('#clearRosterText'),button=$('#clearRosterButton');if(!input||input.value!=='CONFIRMAR'||!button)return;button.disabled=true;button.textContent='Removendo…';try{const result=await annualApi('/api/admin/roster/students',{method:'DELETE',body:JSON.stringify({confirmation:input.value})});$('#modal-root').innerHTML='';rosterMeta={count:result.count,importedAt:result.importedAt};rosterQuery='';studentFormOriginal='';yearPlan=null;await loadRosterPage(1,'',false);render();toast(`${result.deleted} estudante${result.deleted===1?'':'s'} removido${result.deleted===1?'':'s'}. Registros de atividade preservados.`)}catch(error){button.disabled=false;button.textContent='Remover estudantes';toast(error.message)}}
const annualStyle=document.createElement('style');annualStyle.textContent='.student-form-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.student-form-grid label,.class-add-row label,.annual-confirm-modal label{display:grid;gap:7px;color:var(--muted);font-size:14px;font-weight:700}.student-form-grid input,.class-add-row input,.annual-search input,.year-destination,.annual-confirm-modal input{width:100%;min-width:0;border:1px solid var(--line);border-radius:10px;padding:12px;color:var(--ink);background:#fff}.student-form-actions,.student-pagination,.annual-section-head,.student-list-head,.annual-confirm-row{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.student-form-actions{justify-content:flex-start;margin-top:14px}.student-form-actions .hint{margin:0}.student-search,.annual-search{display:flex;gap:8px;flex:1;min-width:min(100%,300px);max-width:480px}.student-search input,.annual-search input{flex:1}.student-table{min-width:850px}.student-pagination{margin-top:15px}.annual-intro,.annual-classes,.annual-students{max-width:100%;margin-top:18px}.annual-intro h2{font:800 24px Manrope;margin:8px 0}.annual-rule-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-top:18px}.annual-rule-grid div{background:#f4f7fc;border:1px solid var(--line);border-radius:12px;padding:14px;display:grid;gap:5px}.annual-rule-grid span{color:var(--muted);font-size:14px}.annual-section-head{align-items:flex-start}.class-chip-list{display:flex;gap:8px;flex-wrap:wrap;margin:17px 0}.class-chip{display:inline-flex;align-items:center;gap:8px;background:#edf4ff;color:var(--blue);padding:7px 9px;border-radius:9px;font-weight:700}.class-chip button{border:0;background:none;color:var(--blue);font-size:20px;line-height:1;padding:0 2px}.class-add-row{display:flex;align-items:flex-end;gap:10px;max-width:500px}.class-add-row label{flex:1}.class-add-row .btn{white-space:nowrap}.annual-bulk{display:flex;align-items:center;gap:9px;flex-wrap:wrap;margin:18px 0 10px}.annual-bulk span{font-size:13px;color:var(--muted);flex:1 1 280px}.annual-table-scroll{overflow:auto}.annual-table{min-width:780px}.annual-table td:first-child{width:80px}.annual-table input[type=checkbox]{width:20px;height:20px;accent-color:var(--blue)}.annual-table td strong,.annual-table td small{display:block}.annual-table td small{font-size:12px;color:var(--muted);margin-top:3px}.year-destination{max-width:130px}.annual-table tr.invalid-class{background:#fff5f3}.annual-table tr.invalid-class .year-destination{border-color:#d6564a}.annual-error{color:#b34236;font-size:14px}.annual-empty{text-align:center;color:var(--muted);padding:25px}.annual-confirm-row{margin-top:18px;padding-top:16px;border-top:1px solid var(--line)}.annual-confirm-modal{max-width:520px}.annual-confirm-modal p{line-height:1.65;color:var(--muted)}.annual-confirm-modal label{margin-top:18px}.annual-confirm-modal label strong{color:var(--blue)}@media(max-width:700px){.student-form-grid,.annual-rule-grid{grid-template-columns:1fr}.class-add-row{align-items:stretch;flex-direction:column}.student-search,.annual-search{max-width:none}.annual-section-head{align-items:stretch}.annual-section-head>.btn{align-self:flex-start}.annual-confirm-row{align-items:stretch;flex-direction:column}.annual-confirm-row .btn{width:100%}}';document.head.append(annualStyle);const rosterDeleteStyle=document.createElement('style');rosterDeleteStyle.textContent='.student-list-actions{display:flex;align-items:center;justify-content:flex-end;gap:10px;flex:1;min-width:min(100%,320px)}.student-list-actions .student-search{min-width:0}.student-list-actions>.btn{white-space:nowrap}@media(max-width:700px){.student-list-actions{align-items:stretch;flex-direction:column}.student-list-actions .student-search{max-width:none}.student-list-actions>.btn{width:100%}}';document.head.append(rosterDeleteStyle);
const platformPasteCenterStyle=document.createElement('style');platformPasteCenterStyle.textContent='#platformPaste.has-image{display:grid;width:100%;max-width:100%;min-height:0;height:auto;place-items:center}#platformPaste.has-image img{justify-self:center;align-self:center;margin:auto}';document.head.append(platformPasteCenterStyle);
// Vídeos são publicados como links diretos do YouTube; nenhum arquivo de vídeo é enviado.
function isYoutubeVideoUrl(value){try{const url=new URL(value);if(url.protocol!=='https:'||url.username||url.password)return false;const host=url.hostname.toLowerCase(),path=url.pathname;if(host==='youtu.be')return path.length>1;if(host==='youtube.com'||host==='www.youtube.com'||host==='m.youtube.com')return (path==='/watch'&&!!url.searchParams.get('v'))||/^\/(shorts|embed|live)\/[^/]+/.test(path);if(host==='youtube-nocookie.com'||host==='www.youtube-nocookie.com')return /^\/embed\/[^/]+/.test(path);return false}catch{return false}}
storeIcons={play:storeIcons.play||'',apple:storeIcons.apple||'',youtube:storeIcons.youtube||''};
const materialCardBeforeYoutube=materialCard;
materialCard=function(material,type,platformId){if(type!=='video'||!material.url)return materialCardBeforeYoutube(material,type,platformId);const icon=storeIcons.youtube?`<img class="youtube-material-icon" src="${esc(storeIcons.youtube)}" alt="YouTube">`:'<svg class="youtube-material-icon" viewBox="0 0 48 34" role="img" aria-label="YouTube"><path fill="#f03" d="M47 5.3a6 6 0 0 0-4.2-4.2C39.1 0 24 0 24 0S8.9 0 5.2 1.1A6 6 0 0 0 1 5.3C0 9 0 17 0 17s0 8 1 11.7a6 6 0 0 0 4.2 4.2C8.9 34 24 34 24 34s15.1 0 18.8-1.1a6 6 0 0 0 4.2-4.2C48 25 48 17 48 17s0-8-1-11.7Z"/><path fill="#fff" d="m19 24.5 13-7.5-13-7.5z"/></svg>';return `<article class="card material"><div class="fileicon youtube-fileicon">${icon}</div><div><h3>${esc(material.name||'Vídeo tutorial')}</h3><small>Vídeo no YouTube</small></div><button class="btn primary" onclick="openMaterial('${platformId}','video','${esc(material.id)}')">Assistir no YouTube ↗</button></article>`};
const editPlatformBeforeYoutube=editPlatform;
editPlatform=function(id){editPlatformBeforeYoutube(id);const videoFileField=$('#pVideo')?.closest('.field');if(videoFileField)videoFileField.remove();const linkField=$('#pVideoUrl')?.closest('.field');if(linkField){const label=linkField.querySelector('label');if(label)label.textContent='Links dos vídeos no YouTube (um link por linha)';$('#pVideoUrl').placeholder='Cole links do YouTube, um por linha';$('#pVideoUrl').value=''} };
const savePlatformBeforeYoutube=savePlatform;
savePlatform=async function(id,editing){const raw=$('#pVideoUrl')?.value.trim()||'',urls=raw?raw.split(/\r?\n/).map(value=>value.trim()).filter(Boolean):[];if(urls.some(url=>!isYoutubeVideoUrl(url))){toast('Use links HTTPS de vídeos do YouTube, um por linha.');return}const emptyVideoInput=document.createElement('input');emptyVideoInput.type='file';emptyVideoInput.id='pVideo';emptyVideoInput.multiple=true;emptyVideoInput.style.display='none';document.body.append(emptyVideoInput);try{return await savePlatformBeforeYoutube(id,editing)}finally{emptyVideoInput.remove()}};
pendingBrandIcons={play:storeIcons.play,apple:storeIcons.apple,youtube:storeIcons.youtube};
processBrandIcon=function(which,file){if(!file)return;if(!['play','apple','youtube'].includes(which)){toast('Ícone não reconhecido.');return}if(!['image/png','image/jpeg','image/webp','image/svg+xml'].includes(String(file.type||'').toLowerCase())||file.size>5*1024*1024){toast('Use uma imagem PNG, JPG, WebP ou SVG de até 5 MB.');return}const labels={play:'Google Play',apple:'App Store',youtube:'YouTube'},reader=new FileReader();reader.onerror=()=>toast('Não foi possível ler essa imagem. Tente outro arquivo.');reader.onload=()=>{const image=new Image();image.onerror=()=>toast('Não foi possível abrir essa imagem. Tente PNG, JPG, WebP ou SVG.');image.onload=()=>{const canvas=document.createElement('canvas'),scale=Math.min(1,512/Math.max(image.width,image.height));canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));const context=canvas.getContext('2d');if(!context){toast('Não foi possível preparar a imagem neste navegador.');return}try{context.drawImage(image,0,0,canvas.width,canvas.height);const png=canvas.toDataURL('image/png');if(png.length>8*1024*1024){toast('A imagem ficou muito grande. Escolha um ícone mais simples ou com menor resolução.');return}pendingBrandIcons[which]=png;const zone=$(`#brand${which==='play'?'Play':which==='apple'?'Apple':'Youtube'}Preview`);if(zone)zone.innerHTML=storeImagePreview(png,labels[which])}catch{toast('Não foi possível converter essa imagem. Tente salvar como PNG e selecioná-la novamente.')}};image.src=reader.result};reader.readAsDataURL(file)};
function pasteBrandIcon(event,which){const item=[...(event.clipboardData?.items||[])].find(entry=>entry.type.startsWith('image/'));if(!item){toast('Copie uma imagem antes de colar o ícone.');return}const file=item.getAsFile();if(!file){toast('Não foi possível ler a imagem copiada. Tente selecionar o arquivo.');return}event.preventDefault();event.stopPropagation();processBrandIcon(which,file)}
document.addEventListener('paste',event=>{const active=document.activeElement,zone=active?.closest?.('.store-paste-zone'),which=({brandPlayPreview:'play',brandApplePreview:'apple',brandYoutubePreview:'youtube'})[zone?.id||active?.id];if(which)pasteBrandIcon(event,which)});
settingsAdmin=function(){pendingBrandIcons={play:storeIcons.play||'',apple:storeIcons.apple||'',youtube:storeIcons.youtube||''};const editor=`<div class="card brand-icon-settings" style="max-width:900px;margin-top:18px"><h2 class="section-title" style="margin-top:0">Ícones das lojas e do YouTube</h2><p class="sub" style="font-size:14px;margin-bottom:14px">Configure as imagens uma única vez. Elas serão reutilizadas nas plataformas e nos links dos vídeos.</p><div class="store-editor-grid"><div class="store-editor-item"><strong>Google Play</strong><div id="brandPlayPreview" class="store-paste-zone" tabindex="0" onclick="this.focus()">${storeImagePreview(pendingBrandIcons.play,'Google Play')}</div><input type="file" accept="image/png,image/jpeg,image/webp,image/svg+xml" aria-label="Imagem da Google Play" onchange="loadBrandIcon('play',this)"></div><div class="store-editor-item"><strong>App Store</strong><div id="brandApplePreview" class="store-paste-zone" tabindex="0" onclick="this.focus()">${storeImagePreview(pendingBrandIcons.apple,'App Store')}</div><input type="file" accept="image/png,image/jpeg,image/webp,image/svg+xml" aria-label="Imagem da App Store" onchange="loadBrandIcon('apple',this)"></div><div class="store-editor-item"><strong>YouTube</strong><div id="brandYoutubePreview" class="store-paste-zone" tabindex="0" onclick="this.focus()">${storeImagePreview(pendingBrandIcons.youtube,'YouTube')}</div><input type="file" accept="image/png,image/jpeg,image/webp,image/svg+xml" aria-label="Imagem do YouTube" onchange="loadBrandIcon('youtube',this)"></div></div><button class="btn primary" style="margin-top:14px" onclick="saveBrandIcons()">Salvar ícones</button></div>`;return settingsAdminStoreOriginal()+editor};
saveBrandIcons=async function(){const previous=storeIcons,icons={play:pendingBrandIcons.play||'',apple:pendingBrandIcons.apple||'',youtube:pendingBrandIcons.youtube||''};storeIcons=icons;const button=[...document.querySelectorAll('.brand-icon-settings button')].find(item=>item.textContent.includes('Salvar ícones'));if(button){button.disabled=true;button.textContent='Salvando…'}try{const response=await fetch('/api/admin/store-icons',{method:'PUT',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({storeIcons:icons})});let result={};try{result=await response.json()}catch{}if(!response.ok)throw new Error(result.error||'Não foi possível salvar os ícones.');contentConfigured=true;contentRevision=result.revision||contentRevision;save();render();toast('Ícones da Google Play, App Store e YouTube salvos.')}catch(error){storeIcons=previous;toast(error.message||'Não foi possível salvar os ícones.')}finally{const active=[...document.querySelectorAll('.brand-icon-settings button')].find(item=>item.textContent.includes('Salvando…'));if(active){active.disabled=false;active.textContent='Salvar ícones'}}};
const youtubeStyle=document.createElement('style');youtubeStyle.textContent='.brand-icon-settings .store-editor-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.youtube-fileicon{display:grid;place-items:center}.youtube-material-icon{display:block;width:46px;height:34px;max-width:100%;object-fit:contain}.youtube-fileicon .youtube-material-icon:not(img){width:42px;height:30px}@media(max-width:760px){.brand-icon-settings .store-editor-grid{grid-template-columns:1fr}}';document.head.append(youtubeStyle);
render();

// Acesso docente: sessão própria, senha inicial obrigatória e conteúdo separado.
let teacherProfile=null,teacherPlatforms=[],teacherAdminList=[],teacherAdminLoading=false,teacherLoginMode=false;
async function teacherApi(path,options={}){const response=await fetch(path,{credentials:'same-origin',...options});let result={};try{result=await response.json()}catch{}if(!response.ok)throw new Error(result.error||'Não foi possível concluir esta ação.');return result}
async function refreshTeacherMaterials(){if(!teacherProfile||teacherProfile.mustChangePassword)return;try{const result=await teacherApi('/api/teacher/content');if(result.configured){teacherPlatforms=result.content.platforms||[];if(!$('#modal-root')?.children.length)render()}}catch(error){if(error.message.includes('Entre na')){teacherProfile=null;teacherPlatforms=[];page='home';render()}}}
async function loadTeacherAdminList(){teacherAdminLoading=true;render();try{teacherAdminList=(await teacherApi('/api/admin/teachers')).teachers||[]}catch(error){teacherAdminList=[];toast(error.message)}finally{teacherAdminLoading=false;render()}}
async function submitTeacherAccount(){const name=$('#teacherName').value.trim(),email=$('#teacherEmail').value.trim().toLowerCase(),platformIds=[...document.querySelectorAll('input[name="teacherPlatform"]:checked')].map(input=>input.value),button=$('#saveTeacherAccount');if(!name||!email||!platformIds.length){toast('Informe nome, e-mail institucional e ao menos uma plataforma.');return}button.disabled=true;button.textContent='Salvando…';try{const result=await teacherApi('/api/admin/teachers',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,email,platformIds})});teacherAdminList=teacherAdminList.filter(item=>item.email!==result.teacher.email).concat(result.teacher).sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));render();toast(result.created?`Professor cadastrado. Senha inicial: ${result.initialPassword}. Ele deverá criar uma nova senha no primeiro acesso.`:'Cadastro atualizado. As plataformas atribuídas foram salvas.')}catch(error){button.disabled=false;button.textContent='Salvar professor';toast(error.message)}}
async function resetTeacherAccountPassword(email){if(!window.confirm(`Redefinir a senha de ${email}? O professor precisará criar uma nova senha no próximo acesso.`))return;try{const result=await teacherApi('/api/admin/teachers/reset',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email})});teacherAdminList=teacherAdminList.map(item=>item.email===email?{...item,mustChangePassword:true}:item);render();toast(`Senha redefinida para ${result.initialPassword}. Compartilhe-a diretamente com o professor.`)}catch(error){toast(error.message)}}
function teacherAdminView(){const platforms=state.platforms||[];return `<section class="teacher-admin-grid"><article class="card"><h2 class="section-title" style="margin-top:0">Adicionar ou atualizar professor</h2><p class="hint">Use o e-mail institucional e selecione as plataformas que ele leciona. As séries disponíveis seguem a configuração de cada plataforma.</p><div class="field"><label for="teacherName">Nome do professor</label><input id="teacherName" autocomplete="name" placeholder="Nome completo"></div><div class="field"><label for="teacherEmail">E-mail institucional</label><input id="teacherEmail" type="email" autocomplete="email" placeholder="nome@santainesrs.com.br"></div><fieldset class="teacher-platform-choices"><legend>Plataformas atribuídas</legend>${platforms.map(platform=>`<label><input type="checkbox" name="teacherPlatform" value="${esc(platform.id)}"><span>${esc(platform.name)}<small>${esc((platform.grades||[]).map(id=>GRADE_OPTIONS.find(option=>option.id===id)?.label||id).join(', ')||'Séries configuradas na plataforma')}</small></span></label>`).join('')||'<p class="hint">Cadastre uma plataforma antes de adicionar professores.</p>'}</fieldset><button id="saveTeacherAccount" class="btn primary" onclick="submitTeacherAccount()" ${platforms.length?'':'disabled'}>Salvar professor</button></article><article class="card"><h2 class="section-title" style="margin-top:0">Professores cadastrados</h2>${teacherAdminLoading?'<p class="hint">Carregando professores…</p>':teacherAdminList.map(teacher=>`<div class="teacher-admin-row"><div><strong>${esc(teacher.name)}</strong><small>${esc(teacher.email)}</small><small>Plataformas: ${esc((teacher.platformIds||[]).map(id=>platforms.find(p=>p.id===id)?.name||id).join(', ')||'Nenhuma')}</small><span class="badge">${teacher.mustChangePassword?'Troca de senha pendente':'Acesso ativo'}</span></div><button class="btn outline" onclick="resetTeacherAccountPassword('${esc(teacher.email)}')">Redefinir senha</button></div>`).join('')||(!teacherAdminLoading?'<p class="hint">Nenhum professor cadastrado ainda.</p>':'')}</article></section>`}
const teacherAdminViewBefore=adminView;
adminView=function(){return `<main class="wrap"><div class="welcome"><div><div class="eyebrow">Painel de gestão</div><h1 class="heading">Área da equipe TE</h1><p class="sub">Gerencie plataformas, professores, lista escolar e materiais.</p></div></div><nav class="adminbar"><button class="tab ${adminTab==='platforms'?'active':''}" onclick="adminTab='platforms';render()">Plataformas</button><button class="tab ${adminTab==='roster'?'active':''}" onclick="adminTab='roster';render();loadRosterMeta()">Lista de estudantes</button><button class="tab ${adminTab==='year'?'active':''}" onclick="adminTab='year';render();loadYearPlan()">Ano letivo</button><button class="tab ${adminTab==='teachers'?'active':''}" onclick="adminTab='teachers';loadTeacherAdminList()">Professores</button><button class="tab ${adminTab==='access'?'active':''}" onclick="adminTab='access';render();loadActivityRecords()">Acessos</button><button class="tab ${adminTab==='settings'?'active':''}" onclick="adminTab='settings';render()">Contato de suporte</button></nav>${adminTab==='platforms'?platformAdmin():adminTab==='roster'?rosterAdmin():adminTab==='year'?yearAdmin():adminTab==='teachers'?teacherAdminView():adminTab==='access'?accessAdmin():settingsAdmin()}</main>`};
const teacherEditPlatformBefore=editPlatform;
editPlatform=function(id){teacherEditPlatformBefore(id);const platform=state.platforms.find(item=>item.id===id)||{teacherPdfs:[],teacherVideos:[]};const form=$('.formgrid');if(!form)return;const section=document.createElement('div');section.className='field full teacher-material-editor';section.innerHTML=`<h3>Materiais exclusivos para professores</h3><p class="hint">Estes PDFs e links aparecem somente para professores atribuídos a esta plataforma. Eles seguem as séries configuradas acima.</p><label for="pTeacherPdf">Adicionar PDFs para professores</label><input id="pTeacherPdf" type="file" accept="application/pdf,.pdf" multiple><label for="pTeacherVideoUrl">Adicionar links de vídeos no YouTube (um por linha)</label><textarea id="pTeacherVideoUrl" placeholder="https://youtu.be/..."></textarea><small>Materiais já cadastrados: ${esc([...(platform.teacherPdfs||[]).map(file=>'PDF · '+file.name),...(platform.teacherVideos||[]).map(video=>'Vídeo · '+video.name)].join(' · ')||'nenhum')}</small>`;form.append(section)};
const teacherSavePlatformBefore=savePlatform;
savePlatform=async function(id,editing){if(!$('#pTeacherPdf'))return teacherSavePlatformBefore(id,editing);const raw=$('#pTeacherVideoUrl').value.trim(),urls=raw?raw.split(/\r?\n/).map(value=>value.trim()).filter(Boolean):[];if(urls.some(url=>!isYoutubeVideoUrl(url))){toast('Use links HTTPS válidos do YouTube, um por linha.');return}const files=[...$('#pTeacherPdf').files];if(files.some(file=>file.type!=='application/pdf'||file.size>25*1024*1024)){toast('Cada PDF para professores deve ter até 25 MB.');return}let loaded;try{loaded=await Promise.all(files.map(async file=>({id:'tp'+Date.now()+Math.random().toString(36).slice(2),name:file.name,data:await readAsDataURL(file)})))}catch(error){toast(error.message);return}const addedVideos=urls.map(url=>({id:'tv'+Date.now()+Math.random().toString(36).slice(2),name:'Vídeo para professores',url})),persistOriginal=persistSiteContent;persistSiteContent=async function(){const platform=state.platforms.find(item=>item.id===id);if(platform){platform.teacherPdfs=[...(platform.teacherPdfs||[]),...loaded];platform.teacherVideos=[...(platform.teacherVideos||[]),...addedVideos]}return persistOriginal()};try{await teacherSavePlatformBefore(id,editing)}finally{persistSiteContent=persistOriginal}};
function teacherLoginView(){return `<main class="login"><section class="card login-box"><div class="eyebrow">Área Equipe Professores</div><h1>Acesso do professor</h1><p class="sub">Entre com seu e-mail institucional e senha.</p><form onsubmit="event.preventDefault();loginTeacher()"><div class="field"><label for="teacherLoginEmail">E-mail institucional</label><input id="teacherLoginEmail" type="email" autocomplete="username" placeholder="nome@santainesrs.com.br" required></div><div class="field"><label for="teacherLoginPassword">Senha</label><input id="teacherLoginPassword" type="password" autocomplete="current-password" required></div><button class="btn primary" style="width:100%" type="submit">Entrar na área docente</button></form><button class="btn quiet" style="width:100%;margin-top:10px" onclick="teacherLoginMode=false;render()">Voltar ao acesso de estudantes e responsáveis</button></section></main>`}
async function loginTeacher(){const email=$('#teacherLoginEmail').value.trim().toLowerCase(),password=$('#teacherLoginPassword').value,button=$('.login-box form .primary');button.disabled=true;try{while(contentSyncing)await new Promise(resolve=>setTimeout(resolve,40));await fetch('/api/logout',{method:'POST',credentials:'same-origin'});const result=await teacherApi('/api/teacher/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,password})});finishActivity();state.user=null;teacherProfile=result.teacher;contentSyncing=true;teacherLoginMode=false;page='home';if(teacherProfile.mustChangePassword){render();return}await refreshTeacherMaterials();render()}catch(error){toast(error.message)}finally{if($('.login-box form .primary'))$('.login-box form .primary').disabled=false}}
function teacherPasswordView(){return `<main class="login"><section class="card login-box"><div class="eyebrow">Primeiro acesso</div><h1>Crie sua senha</h1><p class="sub">Por segurança, troque a senha inicial antes de abrir os materiais da escola.</p><form onsubmit="event.preventDefault();saveTeacherPassword()"><div class="field"><label for="teacherNewPassword">Nova senha (mínimo de 4 caracteres)</label><input id="teacherNewPassword" type="password" autocomplete="new-password" minlength="4" required></div><div class="field"><label for="teacherNewPasswordConfirm">Repita a nova senha</label><input id="teacherNewPasswordConfirm" type="password" autocomplete="new-password" minlength="4" required></div><button class="btn primary" style="width:100%" type="submit">Salvar e continuar</button></form></section></main>`}
async function saveTeacherPassword(){const password=$('#teacherNewPassword').value,confirmation=$('#teacherNewPasswordConfirm').value;if(password.length<4){toast('A senha deve ter pelo menos 4 caracteres.');return}if(password!==confirmation){toast('As senhas não coincidem.');return}try{await teacherApi('/api/teacher/password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password,confirmation})});teacherProfile.mustChangePassword=false;await refreshTeacherMaterials();page='home';render();toast('Senha atualizada. Bem-vindo à área docente.')}catch(error){toast(error.message)}}
function teacherHomeView(){return `<main class="wrap"><section class="welcome"><div><div class="eyebrow">Área Equipe Professores</div><h1 class="heading home-heading">Olá, ${esc(teacherProfile?.name||'professor(a)')}</h1><p class="sub">Acesse as plataformas e os materiais da sua área.</p></div><button class="btn quiet" onclick="logoutTeacher()">Sair</button></section><div class="section-title">Plataformas atribuídas <span style="color:#9aa2b1;font-weight:500;font-size:13px">· ${teacherPlatforms.length}</span></div><section class="grid">${teacherPlatforms.length?teacherPlatforms.map(platform=>`<article class="card platform user-platform" onclick="openPlatform('${esc(platform.id)}')">${platformIcon(platform)}<h3>${esc(platform.name)}</h3><p>${esc(platform.summary).slice(0,120)}</p><div class="card-foot"><span>${(platform.pdfs||[]).length+(platform.teacherPdfs||[]).length} PDFs · ${(platform.videos||[]).length+(platform.teacherVideos||[]).length} vídeos</span><span class="arrow">Ver materiais ↗</span></div></article>`).join(''):'<div class="card empty">A Equipe TE ainda não atribuiu plataformas ao seu acesso.</div>'}</section></main>`}
const teacherDetailBefore=detailView;
detailView=function(){if(!teacherProfile)return teacherDetailBefore();const platform=teacherPlatforms.find(item=>item.id===selected);if(!platform){page='home';return teacherHomeView()}const shared=[...(platform.pdfs||[]).map(file=>({...file,type:'pdf'})),...(platform.videos||[]).map(video=>({...video,type:'video'}))],exclusive=[...(platform.teacherPdfs||[]).map(file=>({...file,type:'pdf'})),...(platform.teacherVideos||[]).map(video=>({...video,type:'video'}))];const cards=(items,teacherOnly)=>items.map(item=>`<article class="card material"><div class="fileicon">${item.type==='pdf'?'PDF':'VÍDEO'}</div><div><h3>${esc(item.name)}</h3><small>${item.type==='pdf'?'Documento PDF':'Vídeo no YouTube'}</small></div><button class="btn primary" onclick="${teacherOnly?'openTeacherMaterial':'openMaterial'}('${esc(platform.id)}','${item.type}','${esc(item.id)}')">${item.type==='pdf'?'Visualizar':'Assistir'} ↗</button></article>`).join('');return `<main class="wrap"><button class="crumb" onclick="goHome()">← Voltar às plataformas</button><div class="detail-head">${platformIcon(platform)}<div><h1>${esc(platform.name)}</h1><p>Materiais da sua área docente</p></div></div><div class="info-box"><strong>Como acessar</strong>${esc(platform.summary)}</div><h2 class="section-title">Materiais de apoio</h2><div class="materials">${cards(shared,false)||'<div class="card empty">Nenhum material geral cadastrado.</div>'}</div><h2 class="section-title">Materiais exclusivos para professores</h2><div class="materials">${cards(exclusive,true)||'<div class="card empty">Nenhum material exclusivo publicado para professores.</div>'}</div></main>`};
function openTeacherMaterial(platformId,type,id){const platform=teacherPlatforms.find(item=>item.id===platformId),items=type==='pdf'?platform?.teacherPdfs:platform?.teacherVideos,item=items?.find(value=>value.id===id);if(!item)return;if(item.data){try{const bytes=Uint8Array.from(atob(item.data.split(',')[1]),character=>character.charCodeAt(0)),url=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'})),link=document.createElement('a');link.href=url;link.target='_blank';link.rel='noopener';link.click();setTimeout(()=>URL.revokeObjectURL(url),120000)}catch{toast('Não foi possível abrir este PDF.')}}else if(item.url)window.open(item.url,'_blank','noopener');else toast('Material sem arquivo ou link.');}
const studentOpenMaterialBeforeTeacher=openMaterial;
openMaterial=function(platformId,type,id){if(!teacherProfile)return studentOpenMaterialBeforeTeacher(platformId,type,id);const platform=teacherPlatforms.find(item=>item.id===platformId),item=(type==='pdf'?platform?.pdfs:platform?.videos)?.find(value=>value.id===id);if(!item)return;if(item.data){try{const bytes=Uint8Array.from(atob(item.data.split(',')[1]),character=>character.charCodeAt(0)),url=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'})),link=document.createElement('a');link.href=url;link.target='_blank';link.rel='noopener';link.click();setTimeout(()=>URL.revokeObjectURL(url),120000)}catch{toast('Não foi possível abrir este PDF.')}}else if(item.url)window.open(item.url,'_blank','noopener');};
const openPlatformBeforeTeacher=openPlatform;
openPlatform=function(id){if(!teacherProfile)return openPlatformBeforeTeacher(id);selected=id;page='detail';render()};
async function logoutTeacher(){try{await teacherApi('/api/teacher/logout',{method:'POST'})}catch{}teacherProfile=null;teacherPlatforms=[];teacherLoginMode=false;contentSyncing=false;state.user=null;page='home';menuOpen=false;render()}
function openTeacherArea(){finishActivity();state.admin=false;state.user=null;teacherLoginMode=true;menuOpen=false;page='home';render()}
const headerBeforeTeacher=header;
header=function(){if(teacherProfile)return `<header class="topbar"><div class="brand"><img class="brand-mark" src="assets/colegio-santa-ines.png" alt="Símbolo do Colégio Santa Inês"><div>Colégio Santa Inês<small>CENTRAL DE PLATAFORMAS</small></div></div><div class="navright"><span class="role-pill">Área Equipe Professores</span><button class="menu-toggle" aria-label="Abrir menu" aria-expanded="${menuOpen}" onclick="toggleMenu()"><span></span><span></span><span></span></button></div>${menuOpen?'<nav class="menu-pop"><button onclick="goHome()">⌂ &nbsp;Plataformas</button><button onclick="logoutTeacher()">↪ &nbsp;Sair da área docente</button></nav>':''}</header>`;const markup=headerBeforeTeacher();return menuOpen?markup.replace('</nav>','<button onclick="openTeacherArea()">♧ &nbsp;Área Equipe Professores</button></nav>'):markup};
const homeViewBeforeTeacher=homeView;
homeView=function(){if(teacherProfile)return teacherHomeView();if(teacherLoginMode)return teacherLoginView();const html=homeViewBeforeTeacher();return html.includes('login-box')?html.replace('<section class="card login-box">','<section class="card login-box"><div class="field teacher-access-choice"><label for="accessArea">Área de acesso</label><select id="accessArea" onchange="teacherLoginMode=this.value===\'teachers\';render()"><option value="students">Estudantes e responsáveis</option><option value="teachers">Área Equipe Professores</option></select></div>'):html};
const renderBeforeTeacher=render;
render=function(){const content=state.admin?adminView():teacherProfile?.mustChangePassword?teacherPasswordView():teacherProfile?(page==='detail'?detailView():teacherHomeView()):page==='login'?loginView():page==='reset'?resetView():page==='detail'?detailView():homeView();$('#app').innerHTML=`<div class="shell">${header()}${content}${footer()}</div>`;if(page==='reset')loadResetOptions()};
const syncSiteContentBeforeTeacher=syncSiteContent;
syncSiteContent=async function(){if(teacherProfile){contentSyncing=true;return}contentSyncing=false;return syncSiteContentBeforeTeacher()};
const loginAdminBeforeTeacher=loginAdmin;
loginAdmin=async function(){try{await fetch('/api/teacher/logout',{method:'POST',credentials:'same-origin'})}catch{}teacherProfile=null;teacherPlatforms=[];return loginAdminBeforeTeacher()};
fetch('/api/session',{credentials:'same-origin',cache:'no-store'}).then(response=>response.json()).then(async session=>{if(!session.teacherAuthenticated||state.admin)return;while(contentSyncing)await new Promise(resolve=>setTimeout(resolve,40));teacherProfile=session.teacher;contentSyncing=true;if(teacherProfile?.mustChangePassword){page='home';render()}else{await refreshTeacherMaterials();page='home';render()}}).catch(()=>{});
